-- Syllabus-aligned reviewer lessons (WCC Forensic 1 to 6) with images and in-app videos.
-- Generated by supabase/content/build_reviewers.py; edit the Python sources, not this file.
-- Lessons are published and approved (confirmed by the instructor, 2026-11-23).

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'photography' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: Photography, its history and police uses$t$, $t$Reviewer: Light and its properties$t$, $t$Reviewer: The camera and its lenses$t$, $t$Reviewer: Film, memory cards and printing$t$, $t$Reviewer: Special photography and crime scene photography$t$, $t$Reviewer: Photographs as evidence$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: Photography, its history and police uses$t$, 8, true, 'approved',
     $j$[{"heading": "Meaning of photography", "body": "The word photography comes from two Greek words: phos or photos (light) and graphein (to write or draw). Photography is therefore \"drawing with light\": recording an image of an object through the action of light on a sensitive material (film) or an electronic sensor. The term was popularised in 1839 by the English scientist Sir John Herschel."}, {"heading": "Important personalities and dates", "body": "• Ibn al-Haytham (Alhazen), around 1000 AD: described the camera obscura (\"dark chamber\"), where light through a small hole projects an inverted image.\n• Joseph Nicéphore Niépce, around 1826 to 1827: made the oldest surviving camera photograph, \"View from the Window at Le Gras\", using bitumen on a pewter plate (heliography). The exposure took many hours.\n• Louis Jacques Mandé Daguerre, 1839: introduced the daguerreotype, a one-of-a-kind image on a silvered copper plate. 1839 is generally treated as the birth year of practical photography.\n• William Henry Fox Talbot, 1841: patented the calotype, the first negative-positive process, which allowed many prints from one negative.\n• Alphonse Bertillon, 1880s: standardised police \"mug shots\" (front and profile views) as part of his identification system.", "image": "photo_niepce.webp", "caption": "The oldest surviving camera photograph: Niépce's \"View from the Window at Le Gras\" (about 1826 to 1827).", "credit": "Joseph Nicéphore Niépce, Public domain, via Wikimedia Commons"}, {"heading": "Importance and objectives in police work", "body": "Photography gives investigators a permanent, accurate and complete record that can be studied long after a scene is released. Its objectives are to record the scene as it was found, to identify persons and objects, to preserve evidence that may change or deteriorate, and to present facts clearly in court.\n\nUses in police work include: identification of persons (mug shots, rogues' gallery), crime scene documentation, recording of evidence before collection, documenting injuries, surveillance, traffic accident investigation, laboratory work (fingerprints, documents, firearms), and training."}, {"heading": "Basic photographic principles", "body": "Every photograph needs three things: light from the subject, a lens to focus that light, and a light-sensitive material (film or sensor) to record it. The camera controls how much light enters (aperture), for how long (shutter speed) and how sensitive the recording medium is (ISO). A sharp, correctly exposed, accurately coloured image is the goal of every forensic photograph."}, {"heading": "Watch: photography in crime scene documentation", "body": "This short lecture shows how photography fits into documenting a crime scene together with notes and sketches.", "video": "I8_LAZgN6wU", "video_title": "Documenting the Crime Scene with Photography (CSInetwork)"}, {"heading": "Quick review", "body": "• Photography = phos (light) + graphein (to write): drawing with light.\n• Herschel coined the term (1839); Niépce made the oldest surviving photograph (about 1826 to 1827); Daguerre introduced the daguerreotype (1839); Talbot introduced the negative-positive calotype (1841).\n• Police photography records, identifies, preserves and presents evidence."}]$j$::jsonb,
     $j$[{"term": "Photography", "definition": "The art and science of producing an image through the action of light on a sensitive material or sensor."}, {"term": "Camera obscura", "definition": "Latin for \"dark chamber\"; a darkened box or room where light through a small opening forms an inverted image."}, {"term": "Daguerreotype", "definition": "Early photographic process (1839) producing a single image on a silvered copper plate."}, {"term": "Calotype", "definition": "Talbot's negative-positive paper process that allowed multiple prints from one negative."}, {"term": "Mug shot", "definition": "Standard police identification photograph, usually front view and profile."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: Light and its properties$t$, 8, true, 'approved',
     $j$[{"heading": "Theory and nature of light", "body": "Light is a form of electromagnetic energy that makes things visible. It travels in straight lines at about 300,000 km (186,000 miles) per second in a vacuum.\n\n• Corpuscular theory (Isaac Newton): light is made of tiny particles.\n• Wave theory (Christiaan Huygens): light travels as waves.\n• Quantum theory (Max Planck and Albert Einstein): light is emitted and absorbed in small packets of energy called photons. Modern physics treats light as having both wave and particle properties."}, {"heading": "Electromagnetic radiation and the visible spectrum", "body": "Light is one small part of the electromagnetic spectrum, which also includes radio waves, microwaves, infrared, ultraviolet, X-rays and gamma rays. The human eye sees only wavelengths of roughly 400 to 700 nanometres.\n\nThe colours of the visible spectrum, from longest to shortest wavelength, are red, orange, yellow, green, blue, indigo and violet (ROYGBIV). Just beyond red is infrared (invisible, longer waves); just beyond violet is ultraviolet (invisible, shorter waves). Both are used in forensic photography to reveal things the eye cannot see.", "image": "photo_em_spectrum.webp", "caption": "The electromagnetic spectrum. Visible light is the narrow band between ultraviolet and infrared.", "credit": "Horst Frank, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Properties of light and the RAT law", "body": "When light strikes an object, one or more of three things happen. This is the RAT law:\n• Reflection: light bounces off the surface. We see most objects by reflected light.\n• Absorption: the object takes in the light and converts it to heat. A black object absorbs most light.\n• Transmission: light passes through the object, as with clear glass.\n\nOther properties include refraction (bending of light as it passes from one medium to another, which is how lenses work), diffraction (spreading around edges) and polarisation (vibration in one plane, used with filters to reduce glare)."}, {"heading": "Qualities of light and their importance", "body": "Light is described by its intensity (brightness), colour (wavelength or colour temperature), direction, and quality. Hard light from a small, direct source gives sharp shadows; soft or diffused light from a large source gives gentle shadows.\n\nWithout light there is no photograph. Correct lighting shows the true shape, texture and colour of evidence."}, {"heading": "Guidelines and lighting styles in forensic photography", "body": "• Front lighting: shows the general appearance but flattens texture.\n• Side or oblique lighting: light from a low angle creates shadows that reveal impressions such as footwear marks, tool marks and indented writing.\n• Back lighting or transmitted light: light passes through the subject, useful for watermarks and paper.\n• Bounce or diffused flash: softens harsh shadows and reflections.\nTake several exposures with light from different directions when photographing impressions."}, {"heading": "Quick review", "body": "• Light travels about 300,000 km per second; visible light is about 400 to 700 nm.\n• ROYGBIV: red has the longest wavelength, violet the shortest.\n• RAT law: Reflection, Absorption, Transmission.\n• Oblique lighting reveals impressions and texture."}]$j$::jsonb,
     $j$[{"term": "RAT law", "definition": "When light strikes an object it is Reflected, Absorbed or Transmitted."}, {"term": "Refraction", "definition": "The bending of light as it passes between materials of different density; the basis of lenses."}, {"term": "Visible spectrum", "definition": "The part of the electromagnetic spectrum the eye can see, about 400 to 700 nanometres."}, {"term": "Infrared", "definition": "Invisible radiation with wavelengths longer than red light."}, {"term": "Ultraviolet", "definition": "Invisible radiation with wavelengths shorter than violet light."}, {"term": "Oblique lighting", "definition": "Light from a low, raking angle that casts shadows to reveal surface detail."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: The camera and its lenses$t$, 9, true, 'approved',
     $j$[{"heading": "Early forms of the camera", "body": "The ancestor of every camera is the camera obscura, a dark box or room with a small hole on one side. Later a lens replaced the hole to make the image brighter and sharper, and a light-sensitive plate or film was placed where the image formed. The box camera, view camera and folding camera followed in the 1800s and early 1900s.", "image": "photo_camera_obscura.webp", "caption": "A camera obscura box: light through the lens forms an image that a mirror reflects onto a viewing screen.", "credit": "en:User:Meggar, CC BY-SA 3.0, via Wikimedia Commons"}, {"heading": "Essential parts of a camera", "body": "• Light-tight box (body): keeps out all light except what passes through the lens.\n• Lens: gathers and focuses light to form the image.\n• Diaphragm or aperture: an adjustable opening that controls how much light enters. It is expressed as an f-number; a smaller f-number means a larger opening.\n• Shutter: opens for a set time (shutter speed) to let light reach the film or sensor.\n• Film or image sensor: records the image.\n• Viewfinder: shows what will be photographed.\n• Focusing mechanism: moves the lens so the subject is sharp."}, {"heading": "Main kinds of cameras", "body": "• Point-and-shoot (compact) and box cameras: simple, fixed settings.\n• View camera: large format, bellows, used for highest detail.\n• Rangefinder: focuses with a separate viewing window.\n• Twin-lens reflex (TLR): one lens for viewing, one for taking the picture.\n• Single-lens reflex (SLR) and digital SLR (DSLR): a mirror and prism let the photographer see exactly through the taking lens; the mirror flips up when the picture is taken.\n• Mirrorless cameras and smartphone cameras: show the image electronically from the sensor.\nSLRs and DSLRs are preferred in forensic work because of interchangeable lenses and full manual control.", "image": "photo_slr.webp", "caption": "Cross-section of a single-lens reflex camera: 1 lens, 2 reflex mirror, 3 focal-plane shutter, 4 film or sensor, 5 focusing screen, 6 viewing hood. The mirror flips up when the picture is taken.", "credit": "Bech, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Watch: how a DSLR works", "body": "An animation of the light path through the lens, mirror, shutter and sensor of a DSLR.", "video": "W34sLbAsFhM", "video_title": "How Does a DSLR Camera Work (Animations Xplaned)"}, {"heading": "Types of lenses", "body": "• Convex (converging or positive) lens: thicker at the centre; brings light rays together to form a real image. Camera lenses are converging.\n• Concave (diverging or negative) lens: thinner at the centre; spreads light rays apart.\n\nCamera lenses by focal length:\n• Normal lens: angle of view similar to the human eye (about 50 mm on a 35 mm camera).\n• Wide-angle lens: shorter focal length, wider view; useful for overall scene photographs in small rooms.\n• Telephoto lens: longer focal length, magnifies distant subjects.\n• Zoom lens: variable focal length.\n• Macro lens: focuses very close for life-size images of small evidence."}, {"heading": "Lens aberrations and their correction", "body": "An aberration is a defect that prevents a lens from forming a perfect image.\n• Spherical aberration: rays through the edge and centre focus at different points, giving a soft image.\n• Chromatic aberration: different colours focus at different points, causing colour fringes.\n• Astigmatism: vertical and horizontal lines cannot be focused at the same time.\n• Coma: off-centre points look like comet-shaped blurs.\n• Curvature of field: a flat subject focuses on a curved surface; centre sharp, edges soft.\n• Distortion: straight lines bend outward (barrel) or inward (pincushion).\n\nCorrected lenses: an achromatic lens corrects chromatic aberration for two colours; an apochromatic lens corrects it for three colours; an anastigmat corrects astigmatism. Stopping down the aperture also reduces several aberrations.", "image": "photo_chromatic.webp", "caption": "Chromatic aberration: a simple lens brings different colours to focus at different distances.", "credit": "Bob Mellish, CC BY-SA 3.0, via Wikimedia Commons"}, {"heading": "Quick review", "body": "• Camera essentials: light-tight box, lens, aperture, shutter, film or sensor, viewfinder.\n• Smaller f-number = bigger opening = more light, shallower depth of field.\n• Camera lenses are convex (converging).\n• Six aberrations: spherical, chromatic, astigmatism, coma, curvature of field, distortion.\n• Achromatic and apochromatic lenses correct colour; anastigmats correct astigmatism."}]$j$::jsonb,
     $j$[{"term": "Aperture", "definition": "The adjustable lens opening that controls the amount of light, expressed as an f-number."}, {"term": "Shutter speed", "definition": "The length of time the shutter stays open to expose the film or sensor."}, {"term": "Focal length", "definition": "Distance from the optical centre of the lens to the image plane when focused at infinity."}, {"term": "Depth of field", "definition": "The range of distance in front of and behind the subject that appears sharp."}, {"term": "SLR / DSLR", "definition": "Single-lens reflex camera (film or digital) that lets the photographer view through the taking lens."}, {"term": "Aberration", "definition": "A lens defect that prevents a perfectly sharp, accurate image."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Film, memory cards and printing$t$, 8, true, 'approved',
     $j$[{"heading": "Photographic film", "body": "Film has three main layers: the base (clear plastic support), the emulsion (light-sensitive silver halide crystals suspended in gelatin) and an anti-halation backing that stops light from reflecting back through the film.\n\nCharacteristics of film:\n• Speed (ISO): sensitivity to light. Fast film (high ISO) needs less light but shows more grain.\n• Grain: the visible clumps of silver that form the image.\n• Colour sensitivity: blue-sensitive (ordinary) film responds only to blue and ultraviolet; orthochromatic film responds to blue and green but not red; panchromatic film responds to all visible colours; infrared film also records infrared.\n• Contrast and latitude: how the film handles bright and dark areas."}, {"heading": "Digital memory cards and the evolution of the SD card", "body": "Digital cameras store images on memory cards. The Secure Digital (SD) card was introduced in 1999. Later formats raised the capacity: SDHC (up to 32 GB), SDXC (up to 2 TB) and SDUC (up to 128 TB). Smaller versions, miniSD and microSD, are used in phones and compact devices.\n\nFor evidence, the original card or an exact copy of the original files must be preserved. Working copies are used for enhancement so the original is never altered.", "image": "photo_sd_cards.webp", "caption": "SD, miniSD and microSD cards.", "credit": "Original: 毛抜き; derivative work: Tkgd2007, CC BY-SA 3.0, via Wikimedia Commons"}, {"heading": "Black-and-white processing", "body": "After exposure, film holds an invisible latent image. Processing makes it visible and permanent:\n1. Developer: changes exposed silver halide into black metallic silver. Common developing agents are metol and hydroquinone, with sodium sulfite (preservative), sodium carbonate (accelerator) and potassium bromide (restrainer).\n2. Stop bath: dilute acetic acid stops development.\n3. Fixer (hypo, sodium thiosulfate): removes the unexposed silver halide so the image is no longer light-sensitive.\n4. Washing: removes the chemicals so the image lasts.\n5. Drying.\nThe result is a negative: light areas of the subject appear dark."}, {"heading": "Photographic paper and printing", "body": "Photographic paper carries a light-sensitive emulsion similar to film. Papers differ in base (resin-coated or fibre), surface (glossy, matte) and contrast grade.\n\nPrinting makes a positive from a negative. In contact printing the negative is placed directly on the paper (print is the same size). In projection printing an enlarger projects the negative onto the paper, allowing enlargement. The paper is then developed, stopped, fixed, washed and dried like film. Modern laboratories print digitally with inkjet, laser or dye-sublimation printers."}, {"heading": "Quick review", "body": "• Film layers: base, emulsion (silver halide in gelatin), anti-halation backing.\n• Orthochromatic = not sensitive to red; panchromatic = sensitive to all colours.\n• Processing order: developer → stop bath → fixer → wash → dry.\n• Fixer (hypo) is sodium thiosulfate; stop bath is acetic acid.\n• Keep the original digital file untouched; work on copies."}]$j$::jsonb,
     $j$[{"term": "Emulsion", "definition": "The light-sensitive layer of film or paper: silver halide crystals in gelatin."}, {"term": "Latent image", "definition": "The invisible image formed on exposed film before development."}, {"term": "Panchromatic film", "definition": "Film sensitive to all colours of visible light."}, {"term": "Orthochromatic film", "definition": "Film sensitive to blue and green light but not red."}, {"term": "Fixer (hypo)", "definition": "Sodium thiosulfate solution that removes unexposed silver halide."}, {"term": "Enlarger", "definition": "Projector used to make enlarged prints from negatives."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Special photography and crime scene photography$t$, 9, true, 'approved',
     $j$[{"heading": "Types of forensic photography", "body": "• Photomicrography: photographing a small object through a microscope to show it enlarged (for example fibres, hair, tool marks).\n• Microphotography: the opposite; making a very small photograph of a large object, such as microfilm of documents.\n• Macrophotography (close-up photography): photographing small objects at life size or larger with a macro lens, without a microscope.\n• Ultraviolet photography: reveals fluorescence of body fluids, some inks and document alterations.\n• Infrared photography: reveals erased or obliterated writing, differences in inks, and details hidden under soot or dark stains.\n• Aerial photography and panoramic photography: show the wider area of a scene."}, {"heading": "Basic photographic equipment at the scene", "body": "A camera with manual controls (usually a DSLR), normal, wide-angle and macro lenses, an external flash with an off-camera cord for oblique lighting, a tripod, scales (rulers), evidence markers, a photo log, spare batteries and memory cards, and a grey card or colour chart for accurate colour."}, {"heading": "Advantages of digital cameras", "body": "Instant review of images at the scene, no film processing, easy copying and transmission, recorded date and time (metadata), and low cost per image. The main concern is that digital files can be edited, so agencies keep the original files, record who handled them, and use only documented, reversible enhancement on copies."}, {"heading": "Guidelines in photographing a crime scene", "body": "1. Photograph the scene before anything is moved, touched or collected.\n2. Work from the general to the specific: overall, mid-range, then close-up photographs.\n3. Take close-ups first without a scale, then with a scale, with the camera perpendicular to the surface.\n4. Record every photograph in a photo log (number, time, description, camera position).\n5. Do not include investigators, equipment or vehicles in the frame.\n6. Photograph entrances, exits, victims, injuries and every item of evidence.\n7. Never delete images, even poor ones; gaps raise questions in court."}, {"heading": "Watch: crime scene photography in practice", "body": "A crime scene technician explains how scenes and evidence are photographed.", "video": "ihj4y_EeLRs", "video_title": "Forensic Files: Crime Scene Photography (City of Chandler Police Department)"}, {"heading": "Quick review", "body": "• Photomicrography = through a microscope (enlarged); microphotography = tiny photographs (microfilm).\n• UV shows fluorescence; IR shows erased or obliterated writing.\n• Overall → mid-range → close-up; without scale, then with scale.\n• Keep a photo log and never delete images."}]$j$::jsonb,
     $j$[{"term": "Photomicrography", "definition": "Photography through a microscope to record an enlarged image of a small object."}, {"term": "Microphotography", "definition": "Making very small photographs, such as microfilm copies of documents."}, {"term": "Macrophotography", "definition": "Close-up photography at life size or larger without a microscope."}, {"term": "Photo log", "definition": "A written record of every photograph taken at a scene."}, {"term": "Metadata", "definition": "Information stored with a digital image, such as date, time and camera settings."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc."]$j$::jsonb),
    (m, base + 6, $t$Reviewer: Photographs as evidence$t$, 7, true, 'approved',
     $j$[{"heading": "Theories on photographic evidence", "body": "• Pictorial testimony theory: the photograph illustrates a witness's testimony. A witness who knows the scene testifies that the photograph is a fair and accurate representation of what they saw.\n• Silent witness theory: the photograph \"speaks for itself\". It is admitted on proof that the process that produced it is reliable, as with an automatic surveillance camera, even when no person saw the event."}, {"heading": "Requirements for admissibility", "body": "A photograph is generally admitted when it is:\n• Relevant to a fact in issue.\n• Authenticated: shown to be a faithful and accurate representation of the subject, by the photographer or another competent witness.\n• Not misleading or unduly prejudicial; gruesome images must still help the court understand a fact.\n\nUnder the Philippine Rules on Electronic Evidence, photographic, audio and video evidence of events, acts or transactions is admissible if it is shown, presented or displayed to the court and identified, explained or authenticated by the person who made the recording or by another competent witness."}, {"heading": "Guidelines for admissible digital photographs", "body": "• Preserve the original files and store them securely.\n• Keep a chain of custody: who took, copied, transferred and stored each file.\n• Use a photo log and keep the image numbering complete.\n• Enhance only copies, using documented methods that do not add or remove content (for example brightness and contrast). Record every step.\n• The photographer should be ready to testify on the camera, settings, lighting and scale used."}, {"heading": "Quick review", "body": "• Pictorial testimony: a witness vouches for the photo. Silent witness: the reliable process vouches for it.\n• Admissibility: relevant, authenticated, not misleading.\n• Keep originals, a chain of custody and a photo log."}]$j$::jsonb,
     $j$[{"term": "Pictorial testimony theory", "definition": "A photograph is admitted to illustrate a witness's testimony about what they observed."}, {"term": "Silent witness theory", "definition": "A photograph is admitted on proof of the reliability of the process that produced it."}, {"term": "Authentication", "definition": "Proof that evidence is what it claims to be."}, {"term": "Chain of custody", "definition": "The documented, unbroken record of everyone who handled an item of evidence."}]$j$::jsonb,
     $j$["Tad-awan, F. P. F. (2024). Forensic photography. Quezon City: Wiseman's Books.", "Villarba, W. H. (2022). Forensic photography for criminology students and practitioners with laboratory manual. Quezon City: Wiseman's Books.", "Cabrillas, T. L., & Abelleja, I. W. B. (2023). Forensic science 1: Forensic photography laboratory manual. Wiseman's Books Trading, Inc.", "Supreme Court of the Philippines. Rules on Electronic Evidence, A.M. No. 01-7-01-SC (2001)."]$j$::jsonb);
  end loop;
end $mig$;

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'personal-identification' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: Introduction and history of personal identification$t$, $t$Reviewer: Fingerprint principles, patterns and minutiae$t$, $t$Reviewer: Taking fingerprints and kinds of prints$t$, $t$Reviewer: Facial identification, DNA and biometrics$t$, $t$Reviewer: Reliability, law, ethics and identification reports$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: Introduction and history of personal identification$t$, 8, true, 'approved',
     $j$[{"heading": "What personal identification is", "body": "Personal identification is the process of establishing the identity of a person, living or dead, by comparing characteristics with known records. In criminal investigation it is used to identify suspects, victims, witnesses and unknown remains, to link a person to a scene, and to prove identity in court."}, {"heading": "Classification of identification methods", "body": "• Anthropometry: body measurements (Bertillon system).\n• Dactyloscopy: fingerprints, palm prints and footprints.\n• Photography and facial identification: mug shots, portrait parlé, facial comparison.\n• Scars, marks and tattoos (SMT).\n• DNA profiling.\n• Forensic odontology: teeth and dental records.\n• Biometrics: iris, retina, voice, face and other automated systems.\n• Others: handwriting, personal effects, documents and visual recognition by witnesses."}, {"heading": "The Bertillon system", "body": "Alphonse Bertillon, a clerk of the Paris police, introduced anthropometry in the early 1880s. Repeat offenders were identified by a set of precise body measurements (such as head length, head breadth, length of the middle finger, foot and forearm), combined with standard photographs and a systematic verbal description called the portrait parlé. Bertillon is often called the father of criminal identification.", "image": "pid_bertillon_card.webp", "caption": "Bertillon's own anthropometric record card, with measurements and front and profile photographs.", "credit": "Jebulon, CC0, via Wikimedia Commons"}, {"heading": "The development of fingerprint science", "body": "• Johannes Purkinje (1823): described nine fingerprint patterns.\n• Sir William Herschel (1858, India): used handprints and fingerprints on contracts to prevent impersonation.\n• Henry Faulds (1880): proposed using fingerprints left at crime scenes to identify offenders.\n• Sir Francis Galton (1892): published \"Finger Prints\", showing that fingerprints are individual and permanent. Ridge details are still called Galton details.\n• Juan Vucetich (1891 to 1892, Argentina): developed a classification system; his office solved the Rojas murder case, the first criminal case solved by fingerprints.\n• Sir Edward Henry (1897 to 1901): developed the Henry Classification System, adopted by Scotland Yard in 1901 and later worldwide.\n• The Will West case (1903, Leavenworth, USA): two prisoners with nearly identical measurements and appearance were told apart by fingerprints, showing the weakness of anthropometry."}, {"heading": "Quick review", "body": "• Bertillon: anthropometry and portrait parlé, father of criminal identification.\n• Galton: individuality and permanence of fingerprints. Henry: classification system (1901, Scotland Yard). Vucetich: first criminal case (Rojas, 1892).\n• The Will West case ended reliance on anthropometry."}]$j$::jsonb,
     $j$[{"term": "Personal identification", "definition": "Establishing the identity of a person by comparison with known records."}, {"term": "Anthropometry", "definition": "Identification by systematic body measurements (Bertillon system)."}, {"term": "Dactyloscopy", "definition": "The science of fingerprint identification."}, {"term": "Portrait parlé", "definition": "\"Spoken picture\": Bertillon's systematic verbal description of a person's features."}, {"term": "Henry Classification System", "definition": "Fingerprint filing system by Sir Edward Henry, adopted by Scotland Yard in 1901."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 2: Personal Identification Techniques.", "Saferstein, R. Criminalistics: An Introduction to Forensic Science. Pearson.", "Supreme Court of the Philippines. Rule on DNA Evidence, A.M. No. 06-11-5-SC (2007)."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: Fingerprint principles, patterns and minutiae$t$, 9, true, 'approved',
     $j$[{"heading": "Fundamental principles", "body": "• Individuality: no two fingers have identical ridge detail, not even those of identical twins.\n• Permanence: ridge patterns form before birth and do not change during life (except by deep scars) until decomposition.\n• Classifiability: patterns fall into recognisable types, so records can be filed and searched systematically."}, {"heading": "The three basic patterns", "body": "• Loop (about 60 to 65 percent of all patterns): ridges enter from one side, recurve, and exit on the same side. A loop has one delta and one core. An ulnar loop opens toward the little finger; a radial loop opens toward the thumb.\n• Whorl (about 30 to 35 percent): circular or spiral ridges with at least two deltas. Types: plain whorl, central pocket loop whorl, double loop whorl and accidental whorl.\n• Arch (about 5 percent): ridges enter on one side and flow out the other with a rise in the centre. A plain arch has no delta; a tented arch has a sharp upthrust or angle.", "image": "pid_patterns.webp", "caption": "Arch, loop and whorl: the three basic fingerprint pattern types.", "credit": "NIST fingerprint images, public domain via Wikimedia Commons"}, {"heading": "Focal points, ridge counting and tracing", "body": "The delta is the point on a ridge nearest the divergence of two type lines; the core is the approximate centre of the pattern. In loops, the ridge count is the number of ridges crossing an imaginary line between the delta and the core. In whorls, ridge tracing follows the ridge from the left delta toward the right delta and classifies the whorl as inner, meeting or outer."}, {"heading": "Minutiae (ridge characteristics)", "body": "Identification depends on minutiae, the small details of individual ridges:\n• Ridge ending: a ridge that stops.\n• Bifurcation: a ridge that splits into two.\n• Dot or island: a very short ridge.\n• Short ridge.\n• Enclosure or lake: a ridge that splits and rejoins.\n• Spur, bridge and crossover.\nExaminers compare the type, position and relationship of minutiae between a questioned print and a known print.", "image": "pid_minutiae.webp", "caption": "Common fingerprint minutiae.", "credit": "Inaki Rom, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Watch: interpreting fingerprint patterns", "body": "A walkthrough of arches, loops and whorls and their sub-types.", "video": "CmNs-VUldrI", "video_title": "Fingerprint Classification Part 1: Pattern Interpretation (CSInetwork)"}, {"heading": "Quick review", "body": "• Principles: individuality, permanence, classifiability.\n• Loops ~60 to 65% (1 delta), whorls ~30 to 35% (2 deltas), arches ~5% (plain arch has no delta).\n• Ulnar loop opens toward the little finger; radial toward the thumb.\n• Minutiae: ridge ending, bifurcation, dot, short ridge, enclosure."}]$j$::jsonb,
     $j$[{"term": "Delta", "definition": "The triangular point where ridges diverge, nearest the type lines."}, {"term": "Core", "definition": "The approximate centre of a fingerprint pattern."}, {"term": "Ulnar loop", "definition": "A loop that opens toward the little finger (ulna side)."}, {"term": "Radial loop", "definition": "A loop that opens toward the thumb (radius side)."}, {"term": "Minutiae", "definition": "Individual ridge characteristics such as endings and bifurcations, used to identify a print."}, {"term": "Ridge count", "definition": "Number of ridges crossing a line between the delta and the core of a loop."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 2: Personal Identification Techniques.", "Saferstein, R. Criminalistics: An Introduction to Forensic Science. Pearson.", "Supreme Court of the Philippines. Rule on DNA Evidence, A.M. No. 06-11-5-SC (2007)."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: Taking fingerprints and kinds of prints$t$, 7, true, 'approved',
     $j$[{"heading": "Fingerprint taking procedure", "body": "1. Clean and dry the subject's fingers; ink a glass slab or pad thinly and evenly with a roller.\n2. Stand behind and to the left of the subject's right hand; control the finger, not the whole hand.\n3. Roll each finger from nail edge to nail edge so the full pattern and both deltas are recorded. Thumbs are rolled toward the body; fingers are rolled away from the body.\n4. Take the plain (flat) impressions of the four fingers together and the thumbs at the bottom of the card. These check that the rolled prints are in the correct boxes.\n5. Complete the personal data, sign, and have the subject sign."}, {"heading": "The ten-print card", "body": "The ten-print card records rolled impressions of all ten fingers in numbered boxes (right thumb is finger 1, right little finger is 5, left thumb is 6, left little finger is 10) and plain impressions at the bottom, together with the subject's personal information. Many agencies now use livescan devices that capture the same impressions digitally and send them to an Automated Fingerprint Identification System (AFIS)."}, {"heading": "Kinds of prints found at scenes", "body": "• Latent prints: invisible prints left by sweat and oils; they must be developed. Powders are used on smooth, non-porous surfaces; ninhydrin (reacts with amino acids, turns purple) on paper and other porous surfaces; cyanoacrylate (super glue) fuming on non-porous items such as plastic and metal; iodine fuming for fresh prints on paper.\n• Patent or visible prints: made by fingers coated with blood, ink, paint or dirt. They are photographed first.\n• Plastic prints: three-dimensional impressions in soft material such as wax, putty, soap or wet paint. They are photographed with oblique lighting and may be cast."}, {"heading": "Quick review", "body": "• Roll nail to nail; thumbs toward the body, fingers away from the body.\n• Plain impressions verify the order of rolled prints.\n• Latent = invisible; patent = visible; plastic = impressed.\n• Ninhydrin for porous surfaces; cyanoacrylate for non-porous."}]$j$::jsonb,
     $j$[{"term": "Ten-print card", "definition": "Card recording rolled and plain impressions of all ten fingers with personal data."}, {"term": "Latent print", "definition": "An invisible fingerprint that must be developed to be seen."}, {"term": "Patent print", "definition": "A visible print made by a finger coated with a substance such as blood or ink."}, {"term": "Plastic print", "definition": "A three-dimensional print impressed in a soft material."}, {"term": "AFIS", "definition": "Automated Fingerprint Identification System: a computer database that searches fingerprints."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 2: Personal Identification Techniques.", "Saferstein, R. Criminalistics: An Introduction to Forensic Science. Pearson.", "Supreme Court of the Philippines. Rule on DNA Evidence, A.M. No. 06-11-5-SC (2007)."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Facial identification, DNA and biometrics$t$, 9, true, 'approved',
     $j$[{"heading": "Facial identification and portrait parlé", "body": "Facial identification compares a person's face with photographs or descriptions. The portrait parlé (\"spoken picture\") is Bertillon's method of describing a face in standard terms: forehead, nose, ears, lips, chin, eyebrows, eyes and general shape. Witness descriptions, cartographic sketches and computer-generated composites build on the same idea.\n\nScars, marks and tattoos (SMT) and other physical characteristics such as height, build, complexion, hair, deformities and amputations are recorded because they are distinctive and help narrow down identity.", "image": "pid_portrait_parle.webp", "caption": "Bertillon's synoptic chart of facial features used to teach the portrait parlé.", "credit": "Alphonse Bertillon, CC0, via Wikimedia Commons"}, {"heading": "DNA basics", "body": "Deoxyribonucleic acid (DNA) is the genetic material in almost every cell. Except for identical twins, each person's DNA profile is unique. Sources at a scene include blood, saliva, semen, hair roots, skin cells (touch DNA), bones and teeth.\n\nSir Alec Jeffreys developed DNA fingerprinting in 1984. Modern laboratories amplify DNA with the polymerase chain reaction (PCR) and type short tandem repeats (STRs) to produce a profile. Mitochondrial DNA, inherited from the mother, is used for hair shafts, old bones and degraded samples."}, {"heading": "DNA collection, uses and limitations", "body": "Collection: wear gloves and a mask, change gloves between items, air-dry wet stains, package biological evidence in paper (not plastic, which traps moisture and causes decay), label, and keep cool. Collect reference samples (buccal swabs) from victims and suspects.\n\nUses: identifying offenders and victims, linking crimes, paternity and kinship, identifying disaster victims, and freeing the wrongly convicted.\n\nLimitations: contamination, degradation by heat and moisture, mixtures from several people, identical twins, and the fact that finding someone's DNA shows presence or contact, not necessarily guilt.", "video": "jaRKLSWS-d0", "video_title": "Forensics expert explains how DNA is used in criminal investigations"}, {"heading": "Biometrics", "body": "Biometrics identifies people automatically by physiological or behavioural traits:\n• Iris scan: the patterns of the coloured ring of the eye.\n• Retina scan: the pattern of blood vessels at the back of the eye.\n• Face recognition, fingerprint and palm scanners, hand geometry.\n• Voice recognition and signature dynamics (behavioural traits).\nA system can verify (one-to-one: is this person who they claim to be?) or identify (one-to-many: who is this person?). Accuracy, privacy, consent and data protection must be considered.", "image": "pid_iris.webp", "caption": "How an iris recognition system works: capture, segmentation, encoding and matching.", "credit": "Carlos Eduardo Ravello Joo (ORCID · Q139714842), CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Quick review", "body": "• Portrait parlé = systematic verbal description of the face.\n• DNA is unique except for identical twins; package biological evidence in paper.\n• PCR amplifies DNA; STRs are typed for profiles; mtDNA is maternal.\n• Iris = coloured ring patterns; retina = blood vessel pattern."}]$j$::jsonb,
     $j$[{"term": "SMT", "definition": "Scars, marks and tattoos recorded for identification."}, {"term": "DNA profile", "definition": "The pattern of genetic markers (usually STRs) that distinguishes one person from another."}, {"term": "PCR", "definition": "Polymerase chain reaction: a technique that copies small amounts of DNA for analysis."}, {"term": "Mitochondrial DNA", "definition": "DNA in the mitochondria, inherited from the mother; useful for degraded samples."}, {"term": "Biometrics", "definition": "Automated identification by physiological or behavioural characteristics."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 2: Personal Identification Techniques.", "Saferstein, R. Criminalistics: An Introduction to Forensic Science. Pearson.", "Supreme Court of the Philippines. Rule on DNA Evidence, A.M. No. 06-11-5-SC (2007)."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Reliability, law, ethics and identification reports$t$, 8, true, 'approved',
     $j$[{"heading": "Errors and reliability in identification", "body": "Every method can fail when used carelessly. Common causes of error are poor-quality or partial samples, contamination, examiner bias, pressure to reach a result, and over-reliance on database \"hits\". A well-known example is the 2004 Madrid train bombing case, in which a latent print was wrongly attributed to an American lawyer, Brandon Mayfield, before the error was found.\n\nSafeguards include documented procedures, independent verification by a second examiner, blind review, proficiency testing, and reporting limitations honestly."}, {"heading": "Comparing identification methods", "body": "• Fingerprints: highly individual and permanent, inexpensive, large databases; partial or smudged prints limit conclusions.\n• DNA: highly discriminating, works on small traces; slower, costly, sensitive to contamination; does not separate identical twins.\n• Facial identification and eyewitnesses: quick but the least reliable; appearance changes and memory errors are common.\n• Biometrics: fast and automated; depends on system quality and raises privacy concerns."}, {"heading": "Legal basis and rights", "body": "• The Rule on DNA Evidence (A.M. No. 06-11-5-SC, 2007) governs the collection, preservation and presentation of DNA evidence and the factors courts consider in weighing it.\n• Identification evidence must be properly collected, documented and authenticated, with an intact chain of custody, to be admitted.\n• The right against self-incrimination protects against compelled testimony. Taking fingerprints, photographs or physical samples is generally treated as non-testimonial, but it must still follow lawful procedure.\n• The Data Privacy Act of 2012 (R.A. 10173) treats biometric and genetic data as sensitive personal information that must be processed lawfully and protected."}, {"heading": "Ethics and misidentification", "body": "Investigators must respect the dignity and privacy of every person, obtain samples humanely and lawfully, keep records confidential, avoid jumping to conclusions, and correct errors promptly. A misidentification can convict the innocent and let the guilty go free."}, {"heading": "Writing identification reports and court presentation", "body": "A report should state: the request and case details; the items received and how they were marked; the methods and equipment used; the observations; the conclusion and its limitations; and the examiner's name and signature. In court, explain methods in plain language, use enlarged charts to show points of comparison, stay within your expertise, and remain objective."}, {"heading": "Quick review", "body": "• Safeguards: verification, documentation, proficiency testing.\n• Rule on DNA Evidence: A.M. No. 06-11-5-SC (2007).\n• Biometric and genetic data are sensitive personal information (R.A. 10173).\n• A good report states items, methods, findings, conclusion and limitations."}]$j$::jsonb,
     $j$[{"term": "Misidentification", "definition": "Wrongly concluding that evidence came from a particular person."}, {"term": "Verification", "definition": "Independent re-examination of a conclusion by a second qualified examiner."}, {"term": "Sensitive personal information", "definition": "Data such as genetic and biometric information given special protection under the Data Privacy Act."}, {"term": "Rule on DNA Evidence", "definition": "Supreme Court rule (A.M. No. 06-11-5-SC) on the use of DNA evidence in Philippine courts."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 2: Personal Identification Techniques.", "Saferstein, R. Criminalistics: An Introduction to Forensic Science. Pearson.", "Supreme Court of the Philippines. Rule on DNA Evidence, A.M. No. 06-11-5-SC (2007).", "Republic Act No. 10173, Data Privacy Act of 2012."]$j$::jsonb);
  end loop;
end $mig$;

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'chemistry-toxicology' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: Introduction, laboratory safety and evidence handling$t$, $t$Reviewer: Collection, preservation and preliminary examination$t$, $t$Reviewer: Forensic toxicology, poisons and dose$t$, $t$Reviewer: Drugs, controlled substances and alcohol$t$, $t$Reviewer: Legal aspects and forensic report writing$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: Introduction, laboratory safety and evidence handling$t$, 8, true, 'approved',
     $j$[{"heading": "Nature and scope", "body": "Forensic chemistry applies chemistry to legal questions: identifying drugs, poisons, explosives, fire accelerants, paints, inks and other substances. Forensic toxicology is the study of poisons and drugs in the body, their effects, and their role in death, injury or impaired behaviour.\n\nTheir objectives are to identify the substance, measure how much is present, interpret what it did to the person, and present the findings to the court. Both play a central role in drug cases, poisoning, drunk or drugged driving, arson and explosions."}, {"heading": "Pioneers", "body": "• Paracelsus (1493 to 1541): \"All things are poison and nothing is without poison; only the dose makes a thing not a poison.\"\n• Mathieu Orfila (1787 to 1853): published a treatise on poisons in 1814; known as the father of toxicology.\n• James Marsh (1836): developed the Marsh test for detecting arsenic."}, {"heading": "Laboratory rules and hazards", "body": "• Wear personal protective equipment (PPE): lab coat, gloves, safety goggles, and a mask or respirator when needed.\n• Use a fume hood for volatile or toxic chemicals.\n• Never eat, drink or smell chemicals directly; waft vapours toward the nose only when instructed.\n• Label every container; read the Safety Data Sheet (SDS) before use.\n• Add acid to water, never water to acid.\n• Know the location of the eyewash, safety shower, fire extinguisher and spill kit.\n• Dispose of waste in the proper containers.", "image": "chem_ghs.webp", "caption": "GHS hazard pictograms found on chemical labels and Safety Data Sheets.", "credit": "GHS pictograms, public domain via Wikimedia Commons"}, {"heading": "Contamination prevention and chain of custody", "body": "Change gloves between items, use clean or disposable tools, package each item separately, and keep evidence away from reference standards. The chain of custody is the written record of every person who received, held, examined or transferred an item, with dates, times and purpose. Any unexplained gap can make the evidence inadmissible, especially in drug cases.", "image": "chem_evidence_bag.webp", "caption": "Marking and sealing an evidence bag during crime scene training.", "credit": "Spc. Kissta Feldner, Public domain, via Wikimedia Commons"}, {"heading": "Quick review", "body": "• Forensic chemistry identifies substances; forensic toxicology studies poisons and drugs in the body.\n• Paracelsus: the dose makes the poison. Orfila: father of toxicology. Marsh: arsenic test.\n• PPE, fume hood, labels, SDS; acid into water.\n• Chain of custody must be complete and documented."}]$j$::jsonb,
     $j$[{"term": "Forensic chemistry", "definition": "The application of chemistry to legal investigations."}, {"term": "Forensic toxicology", "definition": "The study of poisons and drugs in the body and their legal significance."}, {"term": "PPE", "definition": "Personal protective equipment such as gloves, lab coat and goggles."}, {"term": "SDS", "definition": "Safety Data Sheet describing a chemical's hazards and safe handling."}, {"term": "Chain of custody", "definition": "Documented record of the handling of evidence from collection to court."}]$j$::jsonb,
     $j$["Dascil, A. M., & Santos, R. Q. (2021). Forensic chemistry and toxicology: A worktext (3rd ed.). Wiseman's Book Trading Inc.", "Girard, J. E. (2023). Criminalistics: Forensic science, crime, and terrorism (5th ed.). Jones & Bartlett Learning.", "van Asten, A. (2023). Chemical analysis for forensic evidence. Elsevier.", "Republic Act No. 9165, Comprehensive Dangerous Drugs Act of 2002, as amended by R.A. No. 10640."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: Collection, preservation and preliminary examination$t$, 9, true, 'approved',
     $j$[{"heading": "Collection and preservation of chemical evidence", "body": "• Solids and powders: in clean, sealed containers or evidence bags; never mix items.\n• Liquids: in leak-proof, clean glass or suitable plastic containers.\n• Volatile substances (such as fire accelerants): in airtight metal cans or special bags so vapours do not escape.\n• Biological specimens: refrigerate. Blood for alcohol is collected in tubes with sodium fluoride (preservative) and an anticoagulant such as potassium oxalate.\n• Postmortem specimens commonly include peripheral (femoral) blood, urine, vitreous humour, stomach contents, liver and hair.\nEvery package is sealed, labelled (case number, description, date, time, collector) and listed in the chain of custody before submission to the laboratory."}, {"heading": "Basic laboratory procedures", "body": "• Measurement: use calibrated balances; read volumetric glassware at eye level at the bottom of the meniscus.\n• Solution preparation: prepare and label solutions by concentration (for example percent weight per volume or molarity).\n• Basic reactions: observe colour change, precipitate, gas formation or temperature change.\n• Documentation: record every observation in ink in a bound laboratory notebook, with date and signature. Results that are not documented cannot be defended in court."}, {"heading": "Preliminary (presumptive) examination", "body": "Physical properties such as colour, form, odour (never sniffed directly), solubility, melting point and density give the first clues. Presumptive tests are quick screening tests that suggest, but do not prove, the identity of a substance:\n• Marquis reagent: purple to violet for opiates such as heroin and morphine; orange to brown for amphetamine and methamphetamine.\n• Simon's test: blue for secondary amines such as methamphetamine and MDMA.\n• Scott test (cobalt thiocyanate): blue for cocaine.\n• Duquenois-Levine test: purple in the chloroform layer for marijuana.\n• Thin-layer chromatography (TLC): separates the components of a mixture for comparison with standards.", "image": "chem_marquis.webp", "caption": "A positive Marquis reagent presumptive test.", "credit": "Jack Spades, CC BY 2.0, via Wikimedia Commons"}, {"heading": "Confirmatory testing", "body": "Because presumptive tests can give false positives, results are confirmed by specific instrumental methods such as gas chromatography-mass spectrometry (GC-MS), regarded as the gold standard, and infrared spectroscopy (FTIR). Only confirmed results are reported as the identity of a substance.", "image": "chem_tlc.webp", "caption": "A thin-layer chromatography plate viewed under ultraviolet light.", "credit": "Minciw20, CC0, via Wikimedia Commons"}, {"heading": "Watch: testing procedures in forensic toxicology", "body": "An overview of how toxicology laboratories screen and confirm drugs and poisons.", "video": "lBHZyhzttQo", "video_title": "Forensic Toxicology Part 2: Testing Procedures and Techniques"}, {"heading": "Quick review", "body": "• Volatiles in airtight cans; biological samples refrigerated; blood with sodium fluoride.\n• Presumptive tests screen; confirmatory tests (GC-MS) identify.\n• Marquis: purple = opiates, orange-brown = amphetamines. Scott: blue = cocaine. Simon's: blue = methamphetamine. Duquenois-Levine: purple = marijuana."}]$j$::jsonb,
     $j$[{"term": "Presumptive test", "definition": "A screening test that indicates a substance may be present."}, {"term": "Confirmatory test", "definition": "A specific test that positively identifies a substance, such as GC-MS."}, {"term": "GC-MS", "definition": "Gas chromatography-mass spectrometry; separates and identifies compounds."}, {"term": "TLC", "definition": "Thin-layer chromatography; separates mixtures on a coated plate."}, {"term": "Vitreous humour", "definition": "Fluid in the eye, useful in postmortem toxicology."}]$j$::jsonb,
     $j$["Dascil, A. M., & Santos, R. Q. (2021). Forensic chemistry and toxicology: A worktext (3rd ed.). Wiseman's Book Trading Inc.", "Girard, J. E. (2023). Criminalistics: Forensic science, crime, and terrorism (5th ed.). Jones & Bartlett Learning.", "van Asten, A. (2023). Chemical analysis for forensic evidence. Elsevier.", "Republic Act No. 9165, Comprehensive Dangerous Drugs Act of 2002, as amended by R.A. No. 10640."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: Forensic toxicology, poisons and dose$t$, 9, true, 'approved',
     $j$[{"heading": "Toxic substances and poisoning", "body": "A poison is any substance that, when introduced into the body in sufficient quantity, causes illness, injury or death. Poisoning may be accidental, suicidal, homicidal, or occupational and environmental. Branches of forensic toxicology include postmortem toxicology, human performance toxicology (such as impaired driving) and forensic drug testing.", "image": "chem_paracelsus.webp", "caption": "Paracelsus, who taught that the dose makes the poison.", "credit": "A.Hirschvogel, Public domain, via Wikimedia Commons"}, {"heading": "Routes of exposure", "body": "• Ingestion: through the mouth.\n• Inhalation: breathing in gases, vapours or smoke; the fastest route into the blood after injection.\n• Injection: into a vein, muscle or under the skin.\n• Dermal absorption: through the skin or mucous membranes.\nThe effect also depends on the dose, frequency, age, body weight, health, tolerance and the presence of other substances."}, {"heading": "The dose-response relationship", "body": "As the dose increases, the effect increases. Toxicity is compared with the LD50: the dose that kills 50 percent of a test population. The lower the LD50, the more toxic the substance. Acute poisoning results from a single large exposure; chronic poisoning from repeated small exposures over time.", "image": "chem_dose_response.webp", "caption": "A dose-response curve. The LD50 is the dose at which half of the test population dies.", "credit": "Forensim diagram"}, {"heading": "Classification and effects of toxic substances", "body": "• Corrosives: strong acids (sulfuric, nitric, hydrochloric) and alkalis (sodium hydroxide) destroy tissue on contact.\n• Irritants: metallic poisons such as arsenic, mercury and lead, and some plant and animal poisons, inflame tissues.\n• Neurotics: act on the nervous system, such as narcotics, sedatives and deliriants.\n• Asphyxiants: prevent the body from using oxygen. Carbon monoxide binds to haemoglobin (carboxyhaemoglobin, cherry-red discolouration); cyanide blocks cellular respiration and may give a bitter almond odour.\n• Others: alcohol, drugs, pesticides and toxic gases."}, {"heading": "Watch: what forensic toxicology is", "body": "An introduction to the work of a forensic toxicologist.", "video": "Mt9YJx_TfHI", "video_title": "Forensic Toxicology Part 1: What is it?"}, {"heading": "Quick review", "body": "• Routes: ingestion, inhalation, injection, dermal absorption.\n• Lower LD50 = more toxic.\n• Corrosives destroy tissue; irritants inflame; neurotics affect nerves; asphyxiants block oxygen use.\n• Carbon monoxide: cherry-red discolouration. Cyanide: bitter almond odour."}]$j$::jsonb,
     $j$[{"term": "Poison", "definition": "A substance that causes harm or death when it enters the body in sufficient quantity."}, {"term": "LD50", "definition": "The dose that is lethal to 50 percent of a test population."}, {"term": "Acute poisoning", "definition": "Harm from a single large exposure."}, {"term": "Chronic poisoning", "definition": "Harm from repeated small exposures over time."}, {"term": "Asphyxiant", "definition": "A substance that prevents the body from using oxygen, such as carbon monoxide or cyanide."}]$j$::jsonb,
     $j$["Dascil, A. M., & Santos, R. Q. (2021). Forensic chemistry and toxicology: A worktext (3rd ed.). Wiseman's Book Trading Inc.", "Girard, J. E. (2023). Criminalistics: Forensic science, crime, and terrorism (5th ed.). Jones & Bartlett Learning.", "van Asten, A. (2023). Chemical analysis for forensic evidence. Elsevier.", "Republic Act No. 9165, Comprehensive Dangerous Drugs Act of 2002, as amended by R.A. No. 10640."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Drugs, controlled substances and alcohol$t$, 9, true, 'approved',
     $j$[{"heading": "Classification of drugs by effect", "body": "• Stimulants: speed up the central nervous system, such as methamphetamine (\"shabu\"), amphetamine, cocaine and MDMA (ecstasy).\n• Depressants: slow the nervous system, such as alcohol, benzodiazepines and barbiturates.\n• Narcotics and opioids: relieve pain and cause drowsiness, such as morphine, heroin and codeine. Overdose stops breathing.\n• Hallucinogens: alter perception, such as LSD and psilocybin.\n• Cannabinoids: marijuana, whose main active compound is THC.\n• Inhalants: solvents and glues that are sniffed."}, {"heading": "Dangerous drugs law in the Philippines", "body": "Republic Act No. 9165, the Comprehensive Dangerous Drugs Act of 2002, penalises acts such as the importation, sale, possession and use of dangerous drugs and the diversion of controlled precursors and essential chemicals (for example ephedrine, used to make methamphetamine). It created the Dangerous Drugs Board (policy) and the Philippine Drug Enforcement Agency (PDEA, enforcement and laboratory). Drug testing follows two steps: a screening test, then a confirmatory test for positive screens."}, {"heading": "Effects on the body and interpreting findings", "body": "A toxicology result states which substance was found and, when possible, its concentration in blood or urine. Interpretation considers the specimen type, the time since use, tolerance, and whether the level is consistent with use, impairment or a fatal dose. Detection in urine shows past use, not necessarily impairment at the time of an incident. Toxicologists also consider the offender's welfare: findings can support referral to treatment and rehabilitation, which the law provides for drug dependents."}, {"heading": "Alcohol", "body": "Ethanol is a central nervous system depressant. It is absorbed mainly from the small intestine and eliminated mostly by the liver at a fairly steady rate. Blood alcohol concentration (BAC) is measured by breath analysers and confirmed by blood analysis, usually by gas chromatography.\n\nUnder R.A. 10586, the Anti-Drunk and Drugged Driving Act of 2013, a driver of a private vehicle is considered under the influence at a BAC of 0.05 percent or higher, while drivers of trucks, buses, motorcycles and public utility vehicles must have no alcohol (any BAC above 0.0 percent)."}, {"heading": "Quick review", "body": "• Stimulants: shabu, cocaine. Depressants: alcohol, benzodiazepines. Opioids: heroin, morphine. Hallucinogens: LSD. Cannabis: THC.\n• R.A. 9165 (2002): Dangerous Drugs Board and PDEA; screening then confirmatory drug tests.\n• R.A. 10586: BAC 0.05% for private drivers; 0.0% for trucks, buses, motorcycles and PUVs."}]$j$::jsonb,
     $j$[{"term": "Stimulant", "definition": "A drug that increases central nervous system activity."}, {"term": "Depressant", "definition": "A drug that slows central nervous system activity."}, {"term": "Controlled precursor", "definition": "A chemical that can be used to manufacture dangerous drugs and is regulated by law."}, {"term": "BAC", "definition": "Blood alcohol concentration, expressed as a percentage."}, {"term": "PDEA", "definition": "Philippine Drug Enforcement Agency, the lead anti-drug law enforcement agency."}]$j$::jsonb,
     $j$["Dascil, A. M., & Santos, R. Q. (2021). Forensic chemistry and toxicology: A worktext (3rd ed.). Wiseman's Book Trading Inc.", "Girard, J. E. (2023). Criminalistics: Forensic science, crime, and terrorism (5th ed.). Jones & Bartlett Learning.", "van Asten, A. (2023). Chemical analysis for forensic evidence. Elsevier.", "Republic Act No. 9165, Comprehensive Dangerous Drugs Act of 2002, as amended by R.A. No. 10640.", "Republic Act No. 10586, Anti-Drunk and Drugged Driving Act of 2013."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Legal aspects and forensic report writing$t$, 8, true, 'approved',
     $j$[{"heading": "Admissibility of chemical and toxicological evidence", "body": "Laboratory findings are admitted through the testimony of a qualified forensic chemist or toxicologist, an expert whose special knowledge, training and experience are shown in court. The court weighs the expert's qualifications, the methods used, and whether proper procedures were followed. The integrity and identity of the evidence must be proven from seizure to court."}, {"heading": "Chain of custody in drug cases", "body": "Section 21 of R.A. 9165, as amended by R.A. 10640 (2014), requires that seized drugs be inventoried and photographed immediately after seizure in the presence of the accused (or representative or counsel), an elected public official, and a representative of the National Prosecution Service or the media. The items must be turned over to the PDEA forensic laboratory within 24 hours, and the laboratory must issue its certification of results promptly. Unjustified lapses that cast doubt on the identity and integrity of the drugs can lead to acquittal."}, {"heading": "Interpreting and presenting results", "body": "• Report only what the tests show; distinguish presumptive from confirmed results.\n• State concentrations with units and the specimen type.\n• Explain limitations, such as possible degradation or contamination.\n• Avoid opinions outside your expertise; stay objective whichever side called you."}, {"heading": "Parts of a forensic chemistry report", "body": "1. Case and request details (requesting officer, date and time received).\n2. Specimens submitted, with description, weight or volume, and markings.\n3. Purpose of the examination.\n4. Methods and tests performed.\n5. Findings or results.\n6. Conclusion.\n7. Remarks and disposition of the specimens.\n8. Name, signature and position of the examiner, and approval of the head of office.\nIntegrity and accountability matter: never alter results, and correct errors openly."}, {"heading": "Quick review", "body": "• Experts must show qualifications; methods must be sound.\n• R.A. 10640: inventory and photographs with the accused, an elected official, and a prosecution or media representative; laboratory within 24 hours.\n• Reports separate presumptive from confirmed results and state limitations."}]$j$::jsonb,
     $j$[{"term": "Expert witness", "definition": "A witness allowed to give opinions because of special knowledge, skill, training or experience."}, {"term": "Corpus delicti", "definition": "The body of the crime; in drug cases, the seized drug itself."}, {"term": "Inventory", "definition": "The listing and photographing of seized items immediately after seizure."}, {"term": "Certification of results", "definition": "The laboratory's official statement of its findings."}]$j$::jsonb,
     $j$["Dascil, A. M., & Santos, R. Q. (2021). Forensic chemistry and toxicology: A worktext (3rd ed.). Wiseman's Book Trading Inc.", "Girard, J. E. (2023). Criminalistics: Forensic science, crime, and terrorism (5th ed.). Jones & Bartlett Learning.", "van Asten, A. (2023). Chemical analysis for forensic evidence. Elsevier.", "Republic Act No. 9165, Comprehensive Dangerous Drugs Act of 2002, as amended by R.A. No. 10640."]$j$::jsonb);
  end loop;
end $mig$;

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'questioned-documents' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: The field of document examination, writing and forgery$t$, $t$Reviewer: The expert witness and the document examiner$t$, $t$Reviewer: Documents and examination instruments$t$, $t$Reviewer: Paper, writing instruments and handwriting identification$t$, $t$Reviewer: Signatures, forgery and alterations$t$, $t$Reviewer: Currency, typewriting and the legal framework$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: The field of document examination, writing and forgery$t$, 8, true, 'approved',
     $j$[{"heading": "Forensic document examination", "body": "Questioned document examination (QDE) is the branch of forensic science that examines documents whose authorship, genuineness, origin or history is disputed. Examiners study handwriting and signatures, typewriting and printing, paper and ink, alterations, erasures, indented writing, and counterfeit money and identification documents.\n\nForensics appears at the crime scene (finding and preserving documents), in the laboratory (examination), in court (expert testimony), and, less accurately, in entertainment. Albert S. Osborn, author of \"Questioned Documents\" (1910), is regarded as the father of modern document examination."}, {"heading": "Document examination in the Philippines", "body": "Document examination is performed by the Questioned Document Examination Division of the PNP Forensic Group (formerly the PNP Crime Laboratory) and by the Questioned Documents Division of the National Bureau of Investigation (NBI). Typical cases involve forged signatures on deeds, checks and contracts, falsified public documents, threatening letters and counterfeit currency."}, {"heading": "The evolution of writing", "body": "Writing developed from pictures to sounds:\n• Pictographs: pictures of objects (cave drawings).\n• Ideographs: symbols for ideas.\n• Cuneiform (Sumerians, around 3200 BC) and hieroglyphics (Egypt).\n• Phonetic and alphabetic writing: the Phoenician alphabet, adapted by the Greeks and Romans into the Latin alphabet used today.\n• In the Philippines, the pre-colonial Baybayin script was used before the Latin alphabet spread."}, {"heading": "A brief history of forgery", "body": "Forgery is as old as writing itself. Roman law punished it under the Lex Cornelia de falsis (81 BC). As seals, signatures, banknotes and official records gained value, forgers imitated them, and courts began calling on experienced penmen, and later trained examiners, to compare writings.", "video": "in5_Cdw3-Ns", "video_title": "What handwriting analysis looks like: a state crime laboratory (KTVB)"}, {"heading": "Quick review", "body": "• QDE examines documents whose genuineness or authorship is disputed.\n• Albert S. Osborn: father of modern document examination (\"Questioned Documents\", 1910).\n• Writing evolved from pictographs and ideographs to alphabets.\n• In the Philippines: PNP Forensic Group and NBI."}]$j$::jsonb,
     $j$[{"term": "Questioned document", "definition": "Any document whose genuineness, authorship or history is in dispute."}, {"term": "Document examiner", "definition": "A trained specialist who scientifically examines questioned documents."}, {"term": "Pictograph", "definition": "A picture representing an object; the earliest form of writing."}, {"term": "Forgery", "definition": "The false making or material alteration of a writing with intent to defraud."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: The expert witness and the document examiner$t$, 7, true, 'approved',
     $j$[{"heading": "The expert witness", "body": "An expert witness is a person who, because of special knowledge, skill, experience, training or education, may give an opinion in court on a matter outside common knowledge. Under the Rules on Evidence, such an opinion may be received if the witness is shown to possess that expertise (Rule 130, Section 52 of the 2019 amendments, formerly Section 49). Expert witnesses may be presented by the prosecution, the defence, or appointed by the court."}, {"heading": "Weight of expert testimony", "body": "Courts are not bound by expert opinions. The judge weighs the expert's qualifications, the reasons and methods given, and the other evidence. On handwriting, Rule 132, Section 22 provides that genuineness may be proved by a witness familiar with the person's writing, or by comparison, made by the witness or the court, with writings admitted or treated as genuine. A judge may therefore examine the writings personally."}, {"heading": "The forensic document examiner", "body": "A competent examiner usually completes a structured training programme of about two years under a qualified examiner, covering handwriting, typewriting and printing, paper and ink, instruments, and courtroom testimony, followed by proficiency testing.\n\nMoral and professional obligations: be objective and impartial; examine before concluding; use adequate standards; report limitations; never let the party that pays influence the opinion; keep evidence secure and confidential; and admit when a question cannot be answered."}, {"heading": "Quick review", "body": "• An expert witness has special knowledge shown in court (Rule 130, Sec. 52).\n• Courts are not bound by experts; Rule 132, Sec. 22 allows comparison by the court.\n• Examiners must be objective, impartial and honest about limitations."}]$j$::jsonb,
     $j$[{"term": "Expert witness", "definition": "A witness permitted to give opinions because of specialised knowledge or skill."}, {"term": "Standards (exemplars)", "definition": "Writings of known origin used for comparison."}, {"term": "Objectivity", "definition": "Basing conclusions only on the evidence, free from bias."}, {"term": "Proficiency test", "definition": "A test of an examiner's competence using samples with known answers."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: Documents and examination instruments$t$, 8, true, 'approved',
     $j$[{"heading": "Kinds of documents", "body": "A document is any material bearing marks, symbols or writing that conveys a message. Under Philippine law:\n• Public documents: written official acts of public officers and documents acknowledged before a notary public.\n• Official documents: issued by a public official in the exercise of their functions.\n• Commercial documents: used by merchants or businesses, such as checks, promissory notes and bills of exchange.\n• Private documents: deeds or instruments executed by private persons without the intervention of a notary or official.\n\nA questioned document is one whose genuineness is disputed. Standards or exemplars are documents of known origin: requested standards are written on request for the examination; collected standards are writings made in the normal course of life."}, {"heading": "Instruments and apparatus", "body": "• Hand lens and magnifiers: first examination of strokes.\n• Stereomicroscope: three-dimensional view of line quality, pen pressure and stroke order.\n• Ultraviolet lamp: shows fluorescence differences in paper and ink, chemical erasures and invisible markings.\n• Infrared viewing and photography: distinguishes inks that look the same and reveals obliterated writing.\n• Video spectral comparator (VSC): combines different light sources and filters to compare inks and reveal alterations.\n• Electrostatic detection apparatus (ESDA): reveals indented writing left on pages beneath the one written on.\n• Oblique (side) lighting and transmitted light: show indentations, erasures, watermarks and paper thinning.\n• Measuring grids and test plates: compare size, spacing, slant and alignment.", "image": "qde_stereo.webp", "caption": "A stereomicroscope, used to study strokes, pen pressure and line crossings.", "credit": "GcG(jawp), Public domain, via Wikimedia Commons"}, {"heading": "Procedures", "body": "Handle documents with clean hands or gloves; never fold, staple, mark or write on them; keep them in protective folders. Examine non-destructively first (visual, magnification, lighting), photograph findings, and only then consider tests that could alter the document."}, {"heading": "Quick review", "body": "• Public, official, commercial and private documents.\n• Requested vs collected standards.\n• UV: fluorescence and chemical erasure. IR: ink differences and obliterations. ESDA: indented writing. VSC: combined light and filters."}]$j$::jsonb,
     $j$[{"term": "Public document", "definition": "An official act or a document acknowledged before a notary public."}, {"term": "Requested standard", "definition": "A writing made on request specifically for comparison."}, {"term": "Collected standard", "definition": "A writing made in the ordinary course of life, collected for comparison."}, {"term": "ESDA", "definition": "Electrostatic detection apparatus, which reveals indented writing."}, {"term": "VSC", "definition": "Video spectral comparator, used to examine inks and alterations under different light."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Paper, writing instruments and handwriting identification$t$, 9, true, 'approved',
     $j$[{"heading": "Paper and its properties", "body": "Paper is a sheet of matted cellulose fibres, usually from wood pulp, cotton or rag. Types include bond, ledger, onionskin, newsprint, coated and security papers. Properties examined include weight and thickness, colour and brightness, opacity, finish, fibre content, watermarks, and fluorescence from optical brighteners. Matching or differing paper can show whether pages belong together or were substituted."}, {"heading": "Writing instruments", "body": "• Pencil: graphite mixed with clay; grades from hard (H) to soft (B).\n• Fountain pen: liquid ink from a reservoir; may show nib tracks and ink pooling.\n• Ballpoint pen (commercialised in the 1940s): thick oil-based paste ink; may show striations, skipping and ink blobs (gooping).\n• Rollerball and gel pens: water-based or gel inks with smooth lines.\n• Felt-tip and markers: porous tips with broad strokes.\nThe instrument affects line quality, so standards should be written with a similar instrument."}, {"heading": "Handwriting: kinds and physiological basis", "body": "Handwriting is a learned neuromuscular skill controlled by the brain; it is sometimes called \"brain writing\". Kinds include cursive (connected) writing, manuscript or print, and block capitals.\n\nDevelopment: a person first copies a school model (copybook). With practice, writing becomes automatic and develops personal habits. In old age or illness it may show tremor and deterioration."}, {"heading": "Principles of handwriting identification", "body": "• No two persons write exactly alike.\n• No one writes exactly the same way twice: natural variation is normal.\n• Class characteristics come from the copybook system and are shared by many writers; individual characteristics are personal habits that identify a writer.\n• Identification rests on a combination of significant individual characteristics, with no unexplained fundamental differences."}, {"heading": "Process of handwriting analysis", "body": "1. Analyse the questioned writing and the standards separately.\n2. Compare them feature by feature: line quality and rhythm, slant, size and proportion, spacing, alignment to the baseline, pen pressure, letter formations, connecting strokes, beginning and ending strokes, pen lifts, and embellishments.\n3. Evaluate the significance of similarities and differences, considering natural variation.\nGood standards are adequate in number, contemporaneous (written around the same time) and similar in content, style and writing instrument.", "video": "MU6MF3ReuEY", "video_title": "Comparison of handwriting samples (Vidya-mitra lecture)"}, {"heading": "Quick review", "body": "• Ballpoint ink is oil-based paste; striations and gooping are typical.\n• Handwriting is \"brain writing\": learned and habitual.\n• No two people write alike; no one writes the same way twice.\n• Class characteristics are shared; individual characteristics identify."}]$j$::jsonb,
     $j$[{"term": "Natural variation", "definition": "The normal differences in repeated writings of the same person."}, {"term": "Class characteristics", "definition": "Features shared by a group of writers, such as a copybook style."}, {"term": "Individual characteristics", "definition": "Personal writing habits that distinguish one writer from others."}, {"term": "Line quality", "definition": "The smoothness, speed and fluency of the written stroke."}, {"term": "Contemporaneous standards", "definition": "Standards written at about the same time as the questioned writing."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Signatures, forgery and alterations$t$, 9, true, 'approved',
     $j$[{"heading": "Signatures", "body": "A signature is a person's name or mark written by them to show identity or approval. Styles include the formal or complete signature (for legal documents), the informal signature (for everyday use) and the careless scrawl (fast, often illegible). Because signatures are written often, they become highly automatic and personal.\n\nCharacteristics of a genuine signature: free, rapid movement; good line quality with natural tapering at the start and end; consistent proportions; and natural variation between signatures. Two signatures that match exactly when overlaid are suspicious, because no one signs exactly the same way twice."}, {"heading": "Classification of forged signatures", "body": "• Simple or spurious forgery: no attempt to copy the genuine signature; the forger simply writes the name.\n• Simulated or copied forgery: a freehand imitation of a model signature.\n• Traced forgery: the outline of a genuine signature is followed, using transmitted light, carbon paper or an indented guide line.\n\nIndications of forgery: tremor, slow drawn strokes, blunt beginnings and endings, unusual pen lifts, patching or retouching, heavy uniform pressure, guide lines or carbon traces, and differences from the writer's habits.", "image": "qde_signatures.webp", "caption": "Genuine and forged signatures from a famous art forgery case, collected for comparison.", "credit": "F.H. Kreuger, biographer of Van Meegeren, CC BY-SA 3.0, via Wikimedia Commons"}, {"heading": "Steps in the examination of signatures", "body": "1. Obtain adequate standards: several genuine signatures from around the same date and of the same type.\n2. Examine the questioned signature under magnification and different lighting for line quality, tremor, pen lifts and tracing marks.\n3. Compare letter forms, proportions, spacing, slant, baseline and pen pressure with the standards.\n4. Evaluate whether differences are natural variation or signs of imitation.\n5. Report the conclusion and its limitations."}, {"heading": "Types of alteration", "body": "• Erasure: mechanical (scraping or rubbing, which disturbs paper fibres) or chemical (ink eradicators that bleach the ink).\n• Obliteration: covering writing with ink, correction fluid or other material.\n• Addition, insertion and interlineation: writing added between lines or words.\n• Substitution: replacing a page or part of a document.\nDetection uses magnification, transmitted and oblique light, ultraviolet and infrared examination. Elements to prove an alteration: that a change was made, what was originally written if possible, and when or by whom when the evidence allows."}, {"heading": "Quick review", "body": "• Forgery types: simple (spurious), simulated (copied), traced.\n• Signs of forgery: tremor, drawn quality, blunt ends, patching, pen lifts.\n• Identical overlaid signatures suggest tracing.\n• Alterations: erasure, obliteration, addition or interlineation, substitution."}]$j$::jsonb,
     $j$[{"term": "Simple forgery", "definition": "A signature written without attempting to copy the genuine one."}, {"term": "Simulated forgery", "definition": "A freehand copy of a genuine signature."}, {"term": "Traced forgery", "definition": "A signature made by following the outline of a genuine signature."}, {"term": "Obliteration", "definition": "Covering writing so it cannot be read."}, {"term": "Interlineation", "definition": "Writing inserted between lines of an existing document."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb),
    (m, base + 6, $t$Reviewer: Currency, typewriting and the legal framework$t$, 9, true, 'approved',
     $j$[{"heading": "Anti-counterfeit measures in modern currency", "body": "Philippine banknotes are issued by the Bangko Sentral ng Pilipinas (BSP). The New Generation Currency series began in 2010, and a polymer ₱1,000 note was introduced in 2022. The BSP teaches the public to Feel, Look and Tilt:\n• Feel: genuine notes have a distinct texture and raised (embossed) prints.\n• Look: hold the note against the light to see the watermark portrait, the security thread and the see-through mark that completes the denomination.\n• Tilt: optically variable ink and devices change colour or image when tilted.\nCounterfeits often feel smooth, lack a true watermark (a printed imitation instead), have blurred fine lines, and show no colour shift. Counterfeit coins may differ in weight, edge reeding, colour and sound.", "image": "qde_watermark.webp", "caption": "A banknote watermark seen against the light, one of the oldest anti-counterfeiting features.", "credit": "Amin, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Typewriting identification", "body": "Typewriters are classified by their mechanism (type bar, typeball or element, daisywheel) and by typeface design and spacing (for example pica, 10 characters per inch, and elite, 12 characters per inch). Class characteristics identify the make and model; individual defects identify the specific machine: misaligned letters, broken or worn characters, letters printing too light on one side, and clogged type.\n\nTo obtain exemplars: type the questioned text and the full keyboard several times on the suspect machine, with a similar ribbon and paper, and remove and keep the ribbon as evidence. The same principles of class and individual characteristics apply to modern printers and photocopiers.", "image": "qde_typewriter.webp", "caption": "Labelled parts of a portable typewriter.", "credit": "Unknown author, Public domain, via Wikimedia Commons"}, {"heading": "Contents of an examination report", "body": "Case and request details; documents received and how they were marked; the examination requested; methods and instruments used; findings; conclusion with its level of certainty; limitations; and the examiner's signature. In presenting handwriting evidence, use enlarged side-by-side charts and explain methods, observations, limitations and conclusions plainly, without exaggeration."}, {"heading": "Legal framework in the Philippines", "body": "• Revised Penal Code, Articles 161 to 176 (Forgeries): counterfeiting the Great Seal, signatures and stamps of the Chief Executive; counterfeiting coins (Arts. 163 to 165); forging treasury or bank notes (Art. 166); illegal possession and use of false notes (Art. 168); falsification by a public officer, employee or notary (Art. 171); falsification by private individuals and use of falsified documents (Art. 172).\n• Rule 132 of the Rules of Court: authentication and proof of documents, including how the genuineness of handwriting is proved (Section 22)."}, {"heading": "Quick review", "body": "• BSP: Feel, Look, Tilt. Watermark, security thread, see-through mark, embossed prints, colour-shifting ink.\n• Typewriter class characteristics give make and model; individual defects identify the machine.\n• RPC Arts. 161 to 176 cover forgeries; Art. 171 public officers, Art. 172 private individuals.\n• Rule 132, Sec. 22: proving handwriting."}]$j$::jsonb,
     $j$[{"term": "Watermark", "definition": "An image formed in paper during manufacture, visible against the light."}, {"term": "Security thread", "definition": "A thin strip embedded in a banknote, visible against the light."}, {"term": "Optically variable ink", "definition": "Ink that changes colour when the note is tilted."}, {"term": "Pica / elite", "definition": "Typewriter spacing of 10 and 12 characters per inch."}, {"term": "Falsification", "definition": "Making a document speak falsely, punished under Articles 171 and 172 of the Revised Penal Code."}]$j$::jsonb,
     $j$["Tumang & Mosqueda (2025). Questioned Document Examination with Laboratory Activities.", "Revised Penal Code of the Philippines, Articles 161 to 176 (Forgeries).", "Rules of Court of the Philippines, Rules 130 and 132 (Evidence), as amended in 2019."]$j$::jsonb);
  end loop;
end $mig$;

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'polygraph' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: Lie detection, history and theories of deception$t$, $t$Reviewer: The nervous system and the polygraph instrument$t$, $t$Reviewer: Polygraph techniques and the pre-test interview$t$, $t$Reviewer: Test administration and chart analysis$t$, $t$Reviewer: Admissibility, ethics, validity and reporting$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: Lie detection, history and theories of deception$t$, 8, true, 'approved',
     $j$[{"heading": "Introduction", "body": "Lie detection is the use of methods to determine whether a person is telling the truth. The polygraph (from the Greek poly, many, and graphein, to write) records several physiological responses at the same time while a person answers questions. It does not detect lies directly; it records bodily changes that may be associated with deception, and an examiner interprets them."}, {"heading": "History and important personalities", "body": "• Ancient methods relied on fear and superstition: the rice test (a suspect chewed dry rice; a dry mouth suggested guilt), trial by ordeal, and similar practices.\n• Angelo Mosso (late 1800s): studied changes in blood circulation and breathing caused by fear.\n• Cesare Lombroso (1895): used the hydrosphygmograph to record blood pressure and pulse changes during interrogation.\n• Vittorio Benussi (1914): studied breathing patterns in deception.\n• William Moulton Marston (1910s): developed a systolic blood pressure deception test.\n• John A. Larson (1921): built the first instrument that continuously recorded blood pressure, pulse and breathing for police use.\n• Leonarde Keeler (1920s to 1930s): made the polygraph portable and practical and added a galvanometer for skin responses; often called the father of the modern polygraph.\n• John E. Reid (1947): introduced the control question technique.\n• Cleve Backster (1960s): developed the zone comparison technique and numerical scoring.", "image": "poly_keeler.webp", "caption": "Leonarde Keeler demonstrating his polygraph in 1937.", "credit": "Agence de presse Meurisse, Public domain, via Wikimedia Commons"}, {"heading": "Psychological theories of deception", "body": "• Fear of detection or punishment: the person fears the consequences of being caught.\n• Conflict theory: two opposing tendencies, to tell the truth and to lie, cause arousal.\n• Conditioned response: lying has been associated with punishment since childhood.\n• Psychological set: the examinee's attention focuses on the question that poses the greatest threat to them, producing the strongest reaction."}, {"heading": "Behavioural indicators", "body": "Nervousness, avoiding eye contact, fidgeting, hesitation and inconsistent stories are often thought to signal lying, but research shows these cues are unreliable: truthful people may be nervous and skilled liars may be calm. Studies find that people judge truth and lies only slightly better than chance. Behaviour should guide further questioning, never decide guilt."}, {"heading": "Quick review", "body": "• Polygraph = poly (many) + graphein (to write).\n• Lombroso: hydrosphygmograph (1895). Larson: first continuous polygraph (1921). Keeler: modern portable polygraph. Reid: control question technique (1947). Backster: zone comparison.\n• Psychological set: attention goes to the most threatening question.\n• Behavioural cues alone are unreliable."}]$j$::jsonb,
     $j$[{"term": "Polygraph", "definition": "An instrument that records several physiological responses simultaneously."}, {"term": "Psychological set", "definition": "The tendency of attention and reaction to focus on the most threatening question."}, {"term": "Hydrosphygmograph", "definition": "Lombroso's device for recording blood pressure and pulse changes."}, {"term": "Deception", "definition": "The deliberate attempt to make another person believe something untrue."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 5: Lie Detection Techniques.", "National Research Council (2003). The Polygraph and Lie Detection. Washington, DC: The National Academies Press."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: The nervous system and the polygraph instrument$t$, 8, true, 'approved',
     $j$[{"heading": "The autonomic nervous system", "body": "The autonomic nervous system controls involuntary body functions and has two divisions:\n• Sympathetic division (\"fight or flight\"): activated by stress or threat. Heart rate and blood pressure rise, breathing changes, sweating increases, pupils dilate, and digestion slows.\n• Parasympathetic division (\"rest and digest\"): calms the body and restores normal functions.\nThe polygraph records the sympathetic changes that occur when a question is perceived as threatening.", "image": "poly_ans.webp", "caption": "The sympathetic and parasympathetic divisions of the autonomic nervous system.", "credit": "Geo-Science-International, CC0, via Wikimedia Commons"}, {"heading": "Physiological changes recorded", "body": "• Respiration: rate, depth and pattern of breathing (suppression, holding, irregularity).\n• Cardiovascular activity: relative blood pressure and heart rate.\n• Electrodermal activity: changes in the skin's electrical conductance caused by sweat gland activity.\n• Peripheral blood flow (in some instruments)."}, {"heading": "Polygraph instrumentation and sensors", "body": "• Pneumograph: two sensors around the chest (thoracic) and abdomen record breathing.\n• Cardiosphygmograph: a blood pressure cuff on the upper arm records relative blood pressure and pulse.\n• Galvanograph or electrodermal sensor: electrodes on two fingers record skin conductance.\n• Motion or activity sensor: a seat pad detects movements that could distort the recording or be used as countermeasures.\nOlder instruments recorded with pens on moving chart paper; modern computerised polygraphs display and store the tracings digitally.", "image": "poly_lafayette.webp", "caption": "A Lafayette polygraph instrument.", "credit": "Deutsches Spionagemuseum Berlin, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Watch: how a polygraph test is done", "body": "A police examiner explains the sensors and demonstrates the test.", "video": "po_DCBGExP4", "video_title": "How it Works: Polygraph Test (City of Bloomington, Minnesota)"}, {"heading": "Quick review", "body": "• Sympathetic = fight or flight; parasympathetic = rest and digest.\n• Pneumograph = breathing; cardiosphygmograph = blood pressure and pulse; galvanograph = skin conductance; motion sensor = movement.\n• The polygraph records arousal, not lies."}]$j$::jsonb,
     $j$[{"term": "Sympathetic nervous system", "definition": "The division that prepares the body for fight or flight."}, {"term": "Pneumograph", "definition": "Sensor that records breathing."}, {"term": "Cardiosphygmograph", "definition": "Component that records relative blood pressure and heart rate."}, {"term": "Electrodermal activity", "definition": "Changes in the skin's electrical conductance due to sweating."}, {"term": "Chart", "definition": "The recorded tracings from one presentation of the question list."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 5: Lie Detection Techniques.", "National Research Council (2003). The Polygraph and Lie Detection. Washington, DC: The National Academies Press."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: Polygraph techniques and the pre-test interview$t$, 8, true, 'approved',
     $j$[{"heading": "Main testing techniques", "body": "• Relevant-Irrelevant Test (RIT): the oldest format; compares reactions to relevant questions (about the crime) with irrelevant ones (\"Is today Monday?\"). Criticised because innocent people may react strongly to any accusatory question.\n• Control (Comparison) Question Test (CQT): compares reactions to relevant questions with comparison questions about general past misconduct that most people find uncomfortable (for example \"Before this year, did you ever lie to get out of trouble?\"). Stronger reactions to relevant questions suggest deception; stronger reactions to comparison questions suggest truthfulness. Variants include the Reid technique and the Backster zone comparison.\n• Guilty Knowledge Test, also called the Concealed Information Test (GKT or CIT): multiple-choice questions about details only the offender would know (\"Was the weapon a knife? a gun? a rope?\"). A consistent reaction to the correct detail suggests knowledge of the crime.\n• Peak of Tension test: a related format that presents items in a known order and looks for rising tension toward the critical item."}, {"heading": "Pre-test interview", "body": "The pre-test is the most important phase. The examiner:\n1. Explains the examinee's rights and obtains written, voluntary consent.\n2. Collects background and checks suitability: health, medication, sleep, food, drugs or alcohol, and mental condition.\n3. Discusses the case and lets the examinee give their version.\n4. Explains how the polygraph works.\n5. Reviews every question with the examinee; there are no surprise questions.\n6. Often runs an acquaintance (stimulation) test, such as a number test, to show the examinee that the instrument responds."}, {"heading": "Question formulation", "body": "Questions should be short, simple and direct; answerable by yes or no; about one issue only; free of legal terms and emotionally loaded words (use \"take\" rather than \"steal\", for example); and clearly limited in time and subject. Relevant questions concern the specific issue under investigation."}, {"heading": "Quick review", "body": "• RIT: relevant vs irrelevant. CQT: relevant vs comparison questions. GKT/CIT: details only the offender knows.\n• Pre-test: rights and consent, suitability, case discussion, question review, acquaintance test.\n• Questions: short, yes or no, one issue, no loaded words."}]$j$::jsonb,
     $j$[{"term": "Relevant question", "definition": "A question about the specific issue being investigated."}, {"term": "Comparison (control) question", "definition": "A question about general past misconduct used for comparison with relevant questions."}, {"term": "Irrelevant question", "definition": "A neutral question used to establish a baseline."}, {"term": "Concealed Information Test", "definition": "A test using details known only to the perpetrator."}, {"term": "Acquaintance test", "definition": "A practice test that familiarises the examinee with the procedure."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 5: Lie Detection Techniques.", "National Research Council (2003). The Polygraph and Lie Detection. Washington, DC: The National Academies Press."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Test administration and chart analysis$t$, 8, true, 'approved',
     $j$[{"heading": "Phases of the examination", "body": "1. Pre-test interview.\n2. In-test (chart collection): the sensors are attached and the question list is asked, usually three to five times (charts), with about 20 to 30 seconds between questions so responses can return to baseline. The examinee sits still, looks ahead and answers only yes or no.\n3. Post-test: the examiner analyses the charts and discusses the results; the examinee may explain reactions."}, {"heading": "Test administration protocols", "body": "Use a quiet, private, comfortable room free from distractions. The examinee should be rested and fit. Questions are asked in a steady, neutral voice. Every chart is labelled and annotated with the questions, answers, and any movements, coughs or noises that could cause artefacts."}, {"heading": "Chart analysis and scoring", "body": "• Global evaluation: the examiner reviews the charts as a whole. It is more subjective.\n• Numerical scoring: each relevant question is compared with nearby comparison questions, channel by channel, and given a score (in the common seven-position scale from -3 to +3). Scores are totalled and compared with set cut-off values.\n• Computer algorithms and empirical scoring systems help standardise decisions.\nResults are reported as: No Deception Indicated (NDI), Deception Indicated (DI), or Inconclusive or No Opinion when the data are insufficient."}, {"heading": "Quick review", "body": "• Phases: pre-test, in-test (chart collection), post-test.\n• Usually three to five charts, 20 to 30 seconds between questions.\n• Numerical scoring compares relevant and comparison questions (-3 to +3).\n• Results: NDI, DI, Inconclusive."}]$j$::jsonb,
     $j$[{"term": "In-test phase", "definition": "The phase in which the charts are recorded."}, {"term": "Artefact", "definition": "A distortion in the tracing not caused by a response to the question, such as movement or coughing."}, {"term": "Numerical scoring", "definition": "A systematic method of assigning scores to reactions on each channel."}, {"term": "NDI / DI", "definition": "No Deception Indicated / Deception Indicated."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 5: Lie Detection Techniques.", "National Research Council (2003). The Polygraph and Lie Detection. Washington, DC: The National Academies Press."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Admissibility, ethics, validity and reporting$t$, 8, true, 'approved',
     $j$[{"heading": "Admissibility in Philippine courts", "body": "Philippine courts do not accept polygraph results as evidence of guilt or innocence. The Supreme Court has said that the polygraph has not attained scientific acceptance as a reliable and accurate means of ascertaining truth or deception (for example, People v. Adoviso, 1999). Polygraph examinations are therefore used as investigative aids: to focus an investigation, verify statements, or eliminate suspects, not as proof in court."}, {"heading": "Constitutional rights and voluntariness", "body": "Under Article III of the Constitution, a person under investigation has the right to remain silent and to counsel (Section 12) and the right against self-incrimination (Section 17). A polygraph examination must be voluntary, with written consent. A person may refuse or stop the test at any time, and refusal must not be treated as evidence of guilt."}, {"heading": "Professional conduct", "body": "The examiner must be properly trained and certified; avoid bias and remain neutral regardless of who requested the test; keep the results confidential and release them only to authorised persons; never use threats, promises or coercion; and record the examination fully."}, {"heading": "Validity issues, countermeasures and criticisms", "body": "A major scientific review by the U.S. National Research Council (2003) found that specific-incident polygraph tests discriminate lying from truth-telling at rates above chance but well below perfection, and that accuracy for broad screening is weaker.\n\n• False positives: truthful but anxious people may appear deceptive.\n• False negatives: deceptive people may pass.\n• Countermeasures: physical (biting the tongue, pressing the toes), mental (counting backwards, thinking exciting thoughts) or drugs, used to distort responses.\n• Examiner bias and poorly worded questions affect results.", "video": "ZsgInxmk92Q", "video_title": "Do Lie Detectors (Polygraphs) Really Work? (Dr. Todd Grande)"}, {"heading": "Report writing", "body": "A polygraph report includes the case reference and requesting party; examinee information and consent; date, time and place; the technique and instrument used; the relevant questions and answers; the result (NDI, DI or Inconclusive) and the examiner's opinion; any admissions made; and the examiner's name and signature. It should state that the result is an investigative opinion."}, {"heading": "Quick review", "body": "• Polygraph results are not admissible as proof of guilt in Philippine courts.\n• The test must be voluntary; refusal is not evidence of guilt.\n• Accuracy is above chance but not perfect; false positives and countermeasures occur.\n• Reports state technique, questions, answers, result and opinion."}]$j$::jsonb,
     $j$[{"term": "Investigative aid", "definition": "A tool that guides an investigation but is not itself proof in court."}, {"term": "False positive", "definition": "A truthful person judged deceptive."}, {"term": "False negative", "definition": "A deceptive person judged truthful."}, {"term": "Countermeasure", "definition": "A deliberate attempt to distort polygraph responses."}]$j$::jsonb,
     $j$["WCC Course Syllabus, Forensic 5: Lie Detection Techniques.", "National Research Council (2003). The Polygraph and Lie Detection. Washington, DC: The National Academies Press.", "1987 Constitution of the Philippines, Article III (Bill of Rights)."]$j$::jsonb);
  end loop;
end $mig$;

do $mig$
declare
  m uuid;
  base int;
begin
  for m in select id from public.modules where slug = 'ballistics' loop
    delete from public.lessons where module_id = m and title = any (array[$t$Reviewer: Introduction and history of forensic ballistics$t$, $t$Reviewer: Ammunition and the cartridge$t$, $t$Reviewer: Bullets and firearms$t$, $t$Reviewer: Class and individual characteristics$t$, $t$Reviewer: Test firing, evidence handling and ballistic reports$t$]);
    select coalesce(max(position), 0) into base from public.lessons where module_id = m;
    insert into public.lessons (module_id, position, title, reading_minutes, published, review_status, sections, key_terms, citations) values
    (m, base + 1, $t$Reviewer: Introduction and history of forensic ballistics$t$, 8, true, 'approved',
     $j$[{"heading": "Meaning and branches", "body": "Ballistics comes from the Greek ballein, \"to throw\", and is related to the Roman ballista, a war machine that hurled stones. It is the science of the motion of projectiles. Forensic ballistics, more precisely firearms identification, is the scientific examination of firearms, ammunition and fired bullets and cartridge cases to answer legal questions.\n\nBranches:\n• Interior ballistics: what happens inside the firearm, from the firing pin striking the primer until the bullet leaves the muzzle.\n• Exterior ballistics: the flight of the bullet from the muzzle to the target (velocity, trajectory, gravity, air resistance).\n• Terminal ballistics: the effect of the bullet on the target, including wound ballistics.\n• Forensic ballistics: the application of all of these to criminal investigation and the courts."}, {"heading": "Historical background", "body": "• Henry Goddard (1835, London): traced a bullet to the mould that made it through a small flaw, one of the first recorded cases of bullet comparison.\n• Alexandre Lacassagne (1889, France): compared rifling marks on a bullet with a suspect's gun.\n• Charles Waite, Philip Gravelle and Calvin Goddard (1920s, New York): founded the Bureau of Forensic Ballistics; Gravelle adapted the comparison microscope (1925).\n• Col. Calvin H. Goddard: regarded as the father of modern firearms identification. His work on the St. Valentine's Day Massacre (1929) led to the first independent scientific crime laboratory, at Northwestern University."}, {"heading": "What firearms examiners determine", "body": "Whether a firearm is functional; the type, make and calibre of a firearm from fired components; whether a bullet or cartridge case was fired from a particular firearm; the approximate distance of a shot from gunshot residue patterns; and serial numbers that have been removed or altered. In the Philippines, the ownership and possession of firearms are regulated by R.A. 10591."}, {"heading": "Quick review", "body": "• Ballistics: from ballein, to throw.\n• Interior (inside the gun), exterior (flight), terminal (effect on target), forensic (court).\n• Calvin Goddard: father of modern firearms identification; Gravelle: comparison microscope.\n• R.A. 10591 regulates firearms in the Philippines."}]$j$::jsonb,
     $j$[{"term": "Ballistics", "definition": "The science of the motion of projectiles."}, {"term": "Interior ballistics", "definition": "Study of events inside the firearm during firing."}, {"term": "Exterior ballistics", "definition": "Study of the projectile's flight from muzzle to target."}, {"term": "Terminal ballistics", "definition": "Study of the projectile's effect on the target."}, {"term": "Firearms identification", "definition": "Determining whether fired components came from a particular firearm."}]$j$::jsonb,
     $j$["Pacling, R. C. (2023). Laboratory manual in forensic ballistics (2nd ed.). Revisa.", "Republic Act No. 10591, Comprehensive Firearms and Ammunition Regulation Act (2013)."]$j$::jsonb),
    (m, base + 2, $t$Reviewer: Ammunition and the cartridge$t$, 9, true, 'approved',
     $j$[{"heading": "Parts of a cartridge", "body": "A cartridge (also called a round) is one complete unit of ammunition. It has four parts:\n1. Bullet: the projectile that leaves the barrel.\n2. Cartridge case: the container, usually brass, that holds everything together.\n3. Gunpowder (propellant): burns rapidly to produce the gas that pushes the bullet.\n4. Primer: a small, impact-sensitive charge that ignites the gunpowder when struck by the firing pin.", "image": "bal_cartridge.webp", "caption": "Parts of a center-fire cartridge: bullet, cartridge case, gunpowder (propellant), rim and primer.", "credit": "Forensim diagram"}, {"heading": "Classification of cartridges by priming", "body": "• Pin-fire: an early type (developed by Lefaucheux in the 1830s and 1840s) with a small pin sticking out of the side of the case; the hammer strikes the pin to fire the primer. Now obsolete.\n• Rim-fire: the priming compound is inside the hollow rim; the firing pin crushes the rim. Used in small calibres such as .22.\n• Center-fire: a separate primer sits in the centre of the base. Boxer primers have their own anvil and the case has one flash hole; Berdan primers have the anvil formed in the case, with two or more flash holes. Most modern ammunition is center-fire.", "image": "bal_ignition.webp", "caption": "Cartridge ignition types, including pin-fire, rim-fire and center-fire (Boxer and Berdan).", "credit": "Grasyl, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Gunpowder", "body": "• Black powder: the oldest propellant, a mixture of about 75 percent potassium nitrate (saltpetre), 15 percent charcoal and 10 percent sulfur. It produces heavy smoke and residue.\n• Smokeless powder: modern propellant based on nitrocellulose. Single-base contains nitrocellulose only; double-base adds nitroglycerin; triple-base adds nitroguanidine."}, {"heading": "Primers", "body": "A primer has a metal cup, the priming mixture and, in Boxer primers, an anvil. Early primers used mercury fulminate, later potassium chlorate (which corroded barrels). Modern primers commonly contain lead styphnate, barium nitrate and antimony sulfide; their particles are a major part of gunshot residue.", "image": "bal_fired_cases.webp", "caption": "Fired rim-fire (left) and center-fire (right) cases. Note where each firing pin struck.", "credit": "muppetspanker, CC BY-SA 2.0, via Wikimedia Commons"}, {"heading": "Watch: cartridge components", "body": "A short explanation of the parts of a cartridge and how they work together when fired.", "video": "o7chlJAD8FI", "video_title": "Cartridge Components (hunter safety course)"}, {"heading": "Quick review", "body": "• Cartridge = bullet + case + gunpowder + primer.\n• Pin-fire (obsolete, pin on the side), rim-fire (primer in the rim), center-fire (primer in the centre).\n• Boxer: one flash hole, anvil in primer. Berdan: two or more flash holes, anvil in case.\n• Black powder 75:15:10; smokeless powder single, double, triple base."}]$j$::jsonb,
     $j$[{"term": "Cartridge", "definition": "A complete round of ammunition: bullet, case, propellant and primer."}, {"term": "Primer", "definition": "Impact-sensitive charge that ignites the propellant."}, {"term": "Rim-fire", "definition": "Cartridge with priming compound inside the rim."}, {"term": "Center-fire", "definition": "Cartridge with a separate primer in the centre of the base."}, {"term": "Smokeless powder", "definition": "Modern nitrocellulose-based propellant."}]$j$::jsonb,
     $j$["Pacling, R. C. (2023). Laboratory manual in forensic ballistics (2nd ed.). Revisa.", "Republic Act No. 10591, Comprehensive Firearms and Ammunition Regulation Act (2013)."]$j$::jsonb),
    (m, base + 3, $t$Reviewer: Bullets and firearms$t$, 9, true, 'approved',
     $j$[{"heading": "The bullet", "body": "A bullet is the projectile fired from a rifled firearm. It may be made of lead, a lead alloy, or lead with a jacket of copper or gilding metal. Common types:\n• Lead bullet (plain lead, round nose, wadcutter).\n• Full metal jacket (FMJ): the core is fully covered except the base.\n• Semi-jacketed, soft point and hollow point: partly exposed or hollow tips designed to expand.\n• Boat tail: tapered base for better flight.\nShotguns fire shells containing many pellets (shot) or a single slug, with wads separating the powder and shot.", "image": "bal_bullets.webp", "caption": "Different bullet types and constructions.", "credit": "Grasyl, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Calibre and gauge", "body": "Calibre is the diameter of the bore measured from land to land, expressed in hundredths of an inch (.38, .45) or millimetres (9 mm). Shotgun bores are expressed in gauge: the number of lead balls of the bore's diameter that make one pound (a 12-gauge bore fits balls weighing 1/12 pound each); the smaller the gauge number, the larger the bore."}, {"heading": "Rifling", "body": "The inside of most handgun and rifle barrels has spiral grooves (cut into the bore) and lands (the raised areas between them). Rifling spins the bullet so it flies point-first and stable. Rifling has a direction of twist (right or left), a number of lands and grooves, their widths, and a rate of twist. Some barrels use polygonal rifling with rounded lands instead of sharp edges.", "image": "bal_rifling_diagram.webp", "caption": "Conventional rifling (left) and polygonal rifling (right), seen from the muzzle.", "credit": "Pbroks13, Public domain, via Wikimedia Commons"}, {"heading": "Firearms and their parts", "body": "Firearms are classified by bore as smooth-bore (shotguns, muskets) or rifled (pistols, revolvers, rifles), and by action as single-shot, revolver, semi-automatic or automatic. Major parts and their functions:\n• Barrel: guides the bullet and imparts spin.\n• Chamber: holds the cartridge at the moment of firing.\n• Breech and breech face: close the rear of the chamber.\n• Firing pin: strikes the primer.\n• Extractor: pulls the fired case from the chamber; ejector: throws it out.\n• Trigger and hammer or striker: fire the weapon.\n• Magazine or cylinder: holds cartridges.\n• Frame or receiver and stock or grip.", "image": "bal_rifling_bore.webp", "caption": "Looking down a rifled barrel: the spiral lands and grooves.", "credit": "Bradley Lanphear for CAT Outdoors, CC BY-SA 4.0, via Wikimedia Commons"}, {"heading": "Quick review", "body": "• FMJ = fully jacketed; hollow point and soft point expand.\n• Calibre: bore diameter land to land. Gauge: smaller number = bigger bore.\n• Lands are raised; grooves are cut. Rifling spins the bullet.\n• Extractor pulls; ejector throws out the fired case."}]$j$::jsonb,
     $j$[{"term": "Lands", "definition": "The raised portions between the grooves inside a rifled barrel."}, {"term": "Grooves", "definition": "The spiral channels cut into the bore of a rifled barrel."}, {"term": "Calibre", "definition": "The diameter of a rifled bore measured from land to land."}, {"term": "Gauge", "definition": "Shotgun bore size based on the number of bore-sized lead balls per pound."}, {"term": "Extractor / ejector", "definition": "Parts that pull the fired case from the chamber and throw it out of the firearm."}]$j$::jsonb,
     $j$["Pacling, R. C. (2023). Laboratory manual in forensic ballistics (2nd ed.). Revisa.", "Republic Act No. 10591, Comprehensive Firearms and Ammunition Regulation Act (2013)."]$j$::jsonb),
    (m, base + 4, $t$Reviewer: Class and individual characteristics$t$, 9, true, 'approved',
     $j$[{"heading": "Class characteristics", "body": "Class characteristics are features determined by the manufacturer's design, shared by every firearm of the same make and model. They can narrow a bullet down to a group of firearms but cannot identify a single gun:\n• Calibre.\n• Number of lands and grooves.\n• Direction of twist (right or left).\n• Width of lands and grooves.\n• Shape of the firing pin and other design features."}, {"heading": "Individual characteristics", "body": "Individual characteristics are random, microscopic marks unique to one firearm. They come from the manufacturing process and from use, wear, rust and damage. On fired bullets they appear as fine striations scratched by the barrel. On fired cartridge cases they include:\n• Firing pin impression.\n• Breech face marks (the case is pushed back against the breech face).\n• Extractor and ejector marks.\n• Chamber marks."}, {"heading": "Manufacturing processes and identification", "body": "Barrels are rifled by cutting, broaching, button rifling, hammer forging or electrochemical methods. The tools wear slightly with every barrel, and machining leaves tiny random irregularities. That is why two barrels made one after the other by the same tool still leave different striations, which is the scientific basis of firearms identification."}, {"heading": "The comparison microscope", "body": "The comparison microscope joins two microscopes with an optical bridge so the examiner sees two objects side by side in one split field. A questioned bullet or case from the scene is placed under one objective and a test-fired specimen from the suspect firearm under the other. If the striations or impressions line up in sufficient agreement, the examiner can conclude that both were fired from the same firearm. Digital systems such as ballistic imaging networks help search large collections.", "image": "bal_comparison.webp", "caption": "A comparison microscope: two specimens viewed side by side through one eyepiece.", "credit": "Tamasflex, CC BY-SA 3.0, via Wikimedia Commons"}, {"heading": "Watch: inside a ballistics laboratory", "body": "A university forensic laboratory demonstrates the comparison of bullets and cartridge cases.", "video": "WGHCTMTh7TE", "video_title": "Ohio University Forensic Chemistry Lab: Ballistics"}, {"heading": "Quick review", "body": "• Class characteristics (design): calibre, lands and grooves, twist, widths.\n• Individual characteristics (random): striations, firing pin, breech face, extractor and ejector marks.\n• Tool wear makes every barrel unique.\n• Comparison microscope: questioned vs test-fired specimen side by side."}]$j$::jsonb,
     $j$[{"term": "Class characteristics", "definition": "Design features shared by all firearms of the same make and model."}, {"term": "Individual characteristics", "definition": "Random microscopic marks unique to one firearm."}, {"term": "Striations", "definition": "Fine parallel scratches on a bullet made by the barrel."}, {"term": "Breech face marks", "definition": "Marks impressed on the cartridge base by the breech face."}, {"term": "Comparison microscope", "definition": "Two microscopes joined by an optical bridge for side-by-side comparison."}]$j$::jsonb,
     $j$["Pacling, R. C. (2023). Laboratory manual in forensic ballistics (2nd ed.). Revisa.", "Republic Act No. 10591, Comprehensive Firearms and Ammunition Regulation Act (2013)."]$j$::jsonb),
    (m, base + 5, $t$Reviewer: Test firing, evidence handling and ballistic reports$t$, 8, true, 'approved',
     $j$[{"heading": "Test firing and the bullet recovery box", "body": "To compare a suspect firearm with evidence, the examiner test-fires it and recovers undamaged bullets and cartridge cases. A bullet recovery box is a long box filled with cotton waste or similar material that slows the bullet gradually; a water tank is also commonly used. The recovered test specimens keep the marks needed for comparison."}, {"heading": "Handling firearms evidence", "body": "• Make the firearm safe first: unload it and record the position of the cartridges, including which chamber of a revolver was under the hammer.\n• Record the make, model, calibre and serial number.\n• Never insert anything into the barrel and avoid touching surfaces that may hold fingerprints or DNA.\n• Mark fired bullets on the base or nose, never on the bearing surface with the striations.\n• Mark cartridge cases inside or near the mouth, away from the firing pin and breech face marks.\n• Package each item separately, seal, label and record the chain of custody."}, {"heading": "Ballistic report writing", "body": "A ballistic report states: the case and request details; a description of each item received (firearm, bullets or slugs, cartridge cases or empty shells) with markings; the examinations performed (function test, class characteristics, test firing, microscopic comparison); the findings; and the conclusion (for example, that the questioned bullet was fired from the submitted firearm). Reports for legal proceedings are illustrated with photographs, macrophotographs and photomicrographs of the firearm and the matching marks."}, {"heading": "Quick review", "body": "• Bullet recovery box (cotton waste) or water tank for test firing.\n• Unload first; record cartridge positions and serial number.\n• Mark bullets on the base or nose; cases inside the mouth.\n• Reports include descriptions, examinations, findings, conclusion and photomicrographs."}]$j$::jsonb,
     $j$[{"term": "Test firing", "definition": "Firing a suspect weapon to obtain known specimens for comparison."}, {"term": "Bullet recovery box", "definition": "A cotton-filled box used to stop test bullets without damaging their marks."}, {"term": "Slug", "definition": "A fired bullet recovered as evidence."}, {"term": "Photomicrograph", "definition": "A photograph taken through a microscope, used to illustrate matching marks."}]$j$::jsonb,
     $j$["Pacling, R. C. (2023). Laboratory manual in forensic ballistics (2nd ed.). Revisa.", "Republic Act No. 10591, Comprehensive Firearms and Ammunition Regulation Act (2013)."]$j$::jsonb);
  end loop;
end $mig$;
